INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Tuyo', 'Preserved', '', 'Easy', '', '1 person', 'approximately 250 kcal per serving', 4294964192, '[{"name": "tuyo", "description": "3-4 pcs (dried salted herring)"}, {"name": "cooking oil for frying", "description": "1 tbsp"}, {"name": "white vinegar", "description": "1 tbsp"}, {"name": "siling labuyo, sliced", "description": "1 pc"}, {"name": "garlic, minced", "description": "1 clove (for dip)"}]'::jsonb, '[{"title": "Step 1", "description": "Heat generous oil in pan over medium heat."}, {"title": "Step 2", "description": "Fry tuyo 3-4 minutes per side until very crispy."}, {"title": "Step 3", "description": "Drain on paper towels."}, {"title": "Step 4", "description": "Make dipping vinegar: combine vinegar, garlic, and chili."}, {"title": "Step 5", "description": "Serve tuyo with dipping vinegar and garlic rice."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Tapa', 'Preserved', '', 'Easy', '', '1 person', 'approximately 600 kcal per serving', 4294964192, '[{"name": "beef sirloin, thinly sliced", "description": "57g"}, {"name": "garlic, minced", "description": "6 cloves"}, {"name": "soy sauce", "description": "1/3 tsp"}, {"name": "sugar", "description": "2/3 tsp"}, {"name": "calamansi juice", "description": "2/3 tsp"}, {"name": "salt", "description": "1/3 tsp"}, {"name": "black pepper", "description": "1/2/3 tsp"}]'::jsonb, '[{"title": "Step 1", "description": "Slice beef against the grain as thin as possible."}, {"title": "Step 2", "description": "Combine garlic, soy sauce, sugar, calamansi, salt, and pepper."}, {"title": "Step 3", "description": "Toss beef in marinade. Refrigerate 24-48 hours."}, {"title": "Step 4", "description": "Optional: air-dry in fridge uncovered for another 24 hours."}, {"title": "Step 5", "description": "Pan-fry in minimal oil over medium-high heat until browned."}, {"title": "Step 6", "description": "Serve as tapsilog: with sinangag (garlic rice) and itlog (fried egg)."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Tapsilog', 'Breakfast', '', 'Easy', '', '1 person', 'approximately 600 kcal per serving', 4294964192, '[{"name": "beef sirloin, thinly sliced", "description": "57g"}, {"name": "soy sauce", "description": "1/3 tsp"}, {"name": "calamansi juice", "description": "2/3 tsp"}, {"name": "brown sugar", "description": "1/3 tsp"}, {"name": "garlic, minced", "description": "1 clove"}, {"name": "ground black pepper", "description": "1/6 tsp"}, {"name": "cooking oil", "description": "2/3 tsp"}, {"name": "garlic fried rice", "description": "1/3 cup"}, {"name": "1 egg", "description": ""}]'::jsonb, '[{"title": "Step 1", "description": "Marinate the beef with soy sauce, calamansi juice, brown sugar, garlic, and black pepper for at least 4 hours or overnight."}, {"title": "Step 2", "description": "Heat oil in a frying pan over medium heat."}, {"title": "Step 3", "description": "Fry the marinated beef until browned and cooked through."}, {"title": "Step 4", "description": "In another pan, cook the sunny-side-up eggs."}, {"title": "Step 5", "description": "Reheat or prepare the garlic fried rice."}, {"title": "Step 6", "description": "Arrange the garlic rice, beef tapa, and egg on a serving plate."}, {"title": "Step 7", "description": "Serve hot with sliced tomatoes or pickled papaya (atchara)."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Longsilog', 'Breakfast', '', 'Easy', '', '1 person', '300 kcal', 4294964192, '[{"name": "pork longganisa", "description": "1 pieces"}, {"name": "garlic fried rice", "description": "1/3 cup"}, {"name": "1 egg", "description": ""}, {"name": "cooking oil", "description": "1/3 tsp"}, {"name": "Sliced tomatoes (optional)", "description": ""}]'::jsonb, '[{"title": "Step 1", "description": "Heat a pan over medium heat and add the longganisa."}, {"title": "Step 2", "description": "Pour in ¼ cup water and cover the pan."}, {"title": "Step 3", "description": "Cook until the water evaporates."}, {"title": "Step 4", "description": "Add the cooking oil and fry the longganisa until browned."}, {"title": "Step 5", "description": "Fry the eggs to your preferred doneness."}, {"title": "Step 6", "description": "Prepare or reheat the garlic fried rice."}, {"title": "Step 7", "description": "Serve together with sliced tomatoes."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Tosilog', 'Breakfast', '', 'Easy', '', '1 person', '300 kcal', 4294964192, '[{"name": "pork tocino", "description": "57g"}, {"name": "garlic fried rice", "description": "1/3 cup"}, {"name": "1 egg", "description": ""}, {"name": "cooking oil", "description": "1/3 tsp"}, {"name": "Cucumber or tomato slices", "description": ""}]'::jsonb, '[{"title": "Step 1", "description": "Place the tocino in a pan with ¼ cup water."}, {"title": "Step 2", "description": "Cook until the water evaporates."}, {"title": "Step 3", "description": "Add oil and fry until lightly caramelized."}, {"title": "Step 4", "description": "Cook the eggs until desired doneness."}, {"title": "Step 5", "description": "Prepare the garlic fried rice."}, {"title": "Step 6", "description": "Arrange the tocino, rice, and egg on a serving plate."}, {"title": "Step 7", "description": "Serve immediately with fresh vegetables."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Bangsilog', 'Breakfast', '', 'Easy', '', '1 person', '300 kcal', 4294964192, '[{"name": "2 boneless milkfish (bangus)", "description": ""}, {"name": "Salt and pepper to taste", "description": ""}, {"name": "cooking oil", "description": "2/3 tsp"}, {"name": "garlic fried rice", "description": "1/3 cup"}, {"name": "1 egg", "description": ""}]'::jsonb, '[{"title": "Step 1", "description": "Season the bangus with salt and pepper."}, {"title": "Step 2", "description": "Heat oil in a frying pan."}, {"title": "Step 3", "description": "Fry the bangus until crispy on both sides."}, {"title": "Step 4", "description": "Remove and drain on paper towels."}, {"title": "Step 5", "description": "Fry the eggs."}, {"title": "Step 6", "description": "Prepare the garlic fried rice."}, {"title": "Step 7", "description": "Serve hot with vinegar dipping sauce."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Corned Beef Silog', 'Breakfast', '', 'Easy', '', '1 person', '300 kcal', 4294964192, '[{"name": "corned beef", "description": "1/2 can"}, {"name": "1/3 onion, chopped", "description": ""}, {"name": "garlic, minced", "description": "1 clove"}, {"name": "cooking oil", "description": "1/3 tsp"}, {"name": "garlic fried rice", "description": "1/3 cup"}, {"name": "1 egg", "description": ""}]'::jsonb, '[{"title": "Step 1", "description": "Heat oil in a pan and sauté the garlic and onion."}, {"title": "Step 2", "description": "Add the corned beef and cook for 5–7 minutes."}, {"title": "Step 3", "description": "Stir occasionally until heated through."}, {"title": "Step 4", "description": "Fry the eggs separately."}, {"title": "Step 5", "description": "Prepare or reheat the garlic fried rice."}, {"title": "Step 6", "description": "Plate the corned beef, rice, and egg together."}, {"title": "Step 7", "description": "Serve while hot."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Daingsilog', 'Breakfast', '', 'Easy', '', '1 person', '300 kcal', 4294964192, '[{"name": "dried fish", "description": "1.3 pieces (daing)"}, {"name": "cooking oil", "description": "2/3 tsp"}, {"name": "garlic fried rice", "description": "1/3 cup"}, {"name": "1 egg", "description": ""}, {"name": "Vinegar for dipping", "description": ""}]'::jsonb, '[{"title": "Step 1", "description": "Rinse the dried fish briefly and pat dry."}, {"title": "Step 2", "description": "Heat oil over medium heat."}, {"title": "Step 3", "description": "Fry the dried fish until crispy."}, {"title": "Step 4", "description": "Fry the eggs separately."}, {"title": "Step 5", "description": "Prepare or reheat the garlic fried rice."}, {"title": "Step 6", "description": "Arrange everything on a serving plate."}, {"title": "Step 7", "description": "Serve with vinegar dipping sauce. Servings: 1 personx`"}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Champorado', 'Breakfast', '', 'Easy', '', '1 person', '300 kcal', 4294964192, '[{"name": "glutinous rice", "description": "1/1 cup"}, {"name": "1 2/1 cups water", "description": ""}, {"name": "cocoa powder or tablea", "description": "1/6 cup"}, {"name": "sugar", "description": "1/6 cup"}, {"name": "evaporated milk", "description": "1/6 cup"}]'::jsonb, '[{"title": "Step 1", "description": "Wash the glutinous rice thoroughly."}, {"title": "Step 2", "description": "Bring the water to a boil in a pot."}, {"title": "Step 3", "description": "Add the rice and cook until tender."}, {"title": "Step 4", "description": "Stir in the cocoa powder or melted tablea."}, {"title": "Step 5", "description": "Add the sugar and mix well."}, {"title": "Step 6", "description": "Simmer until the porridge thickens. Servings: 1 person"}, {"title": "Step 7", "description": "Serve warm with evaporated milk drizzled on top."}, {"title": "Step 8", "description": "Calories: approximately 600 kcal per serving"}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Arroz Caldo', 'Breakfast', '', 'Easy', '', '1 person', '300 kcal', 4294964192, '[{"name": "glutinous rice", "description": "1/1 cup"}, {"name": "chicken, cut into serving pieces", "description": "57g"}, {"name": "chicken broth", "description": "2/3 cups"}, {"name": "1/3 onion, chopped", "description": ""}, {"name": "garlic, minced", "description": "1 clove"}, {"name": "1/3 thumb-sized ginger, julienned", "description": ""}, {"name": "fish sauce", "description": "2/3 tsp"}, {"name": "cooking oil", "description": "2/3 tsp"}, {"name": "Chopped spring onions and boiled eggs for garnish", "description": ""}]'::jsonb, '[{"title": "Step 1", "description": "Heat oil and sauté the garlic, onion, and ginger until fragrant."}, {"title": "Step 2", "description": "Add the chicken and cook until lightly browned."}, {"title": "Step 3", "description": "Stir in the fish sauce."}, {"title": "Step 4", "description": "Add the glutinous rice and chicken broth."}, {"title": "Step 5", "description": "Bring to a boil, then simmer until the rice is soft and the porridge thickens. Servings: 1 person"}, {"title": "Step 6", "description": "Taste and adjust the seasoning if needed."}, {"title": "Step 7", "description": "Calories: approximately 600 kcal per serving"}, {"title": "Step 8", "description": "Garnish with spring onions and boiled eggs before serving."}]'::jsonb);
