INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Goto', 'Breakfast', '', 'Medium', '', '1 person', '300 kcal', 4294964192, '[{"name": "beef tripe, cleaned and boiled until tender", "description": "500g"}, {"name": "glutinous rice", "description": "1 cup"}, {"name": "beef broth", "description": "6 cups"}, {"name": "1 onion, chopped", "description": ""}, {"name": "garlic, minced", "description": "5 cloves"}, {"name": "1 thumb-sized ginger, julienned", "description": ""}, {"name": "fish sauce", "description": "2 tbsp"}, {"name": "cooking oil", "description": "2 tbsp"}, {"name": "Fried garlic and chopped spring onions for garnish", "description": ""}]'::jsonb, '[{"title": "Step 1", "description": "Heat oil and sauté the garlic, onion, and ginger until fragrant. Servings: 1 person"}, {"title": "Step 2", "description": "Add the cooked beef tripe and stir for 2–3 minutes."}, {"title": "Step 3", "description": "Calories: approximately 600 kcal per serving"}, {"title": "Step 4", "description": "Add the glutinous rice and beef broth."}, {"title": "Step 5", "description": "Bring to a boil, then simmer until the rice becomes soft and creamy."}, {"title": "Step 6", "description": "Stir in the fish sauce and cook for another 5 minutes."}, {"title": "Step 7", "description": "Adjust the seasoning if needed."}, {"title": "Step 8", "description": "Garnish with fried garlic and spring onions before serving."}]'::jsonb);
