eggs", "description": ""}, {"name": "Vinegar for dipping Servings: 1 person", "description": ""}]'::jsonb, '[{"title": "Step 1", "description": "Calories: approximately 600 kcal per serving"}, {"title": "Step 2", "description": "Heat oil in a frying pan."}, {"title": "Step 3", "description": "Fry the smoked milkfish until heated through and slightly crispy."}, {"title": "Step 4", "description": "Fry the eggs separately."}, {"title": "Step 5", "description": "Prepare or reheat the garlic fried rice."}, {"title": "Step 6", "description": "Arrange the fish, rice, and egg on a serving plate."}, {"title": "Step 7", "description": "Serve with sliced tomatoes."}, {"title": "Step 8", "description": "Enjoy with vinegar dipping sauce."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Sardinas Silog', 'Breakfast', '', 'Easy', '', '1 person', '300 kcal', 4294964192, '[{"name": "sardines in tomato sauce", "description": "2 cans"}, {"name": "1 onion, chopped", "description": ""}, {"name": "garlic, minced", "description": "3 cloves"}, {"name": "cooking oil", "description": "1 tbsp"}, {"name": "garlic fried rice Servings: 1 person", "description": "3 cups"}, {"name": "3 eggs", "description": ""}]'::jsonb, '[{"title": "Step 1", "description": "Heat oil and sauté the garlic and onion until fragrant."}, {"title": "Step 2", "description": "Add the canned sardines with the sauce."}, {"title": "Step 3", "description": "Simmer for 5 minutes."}, {"title": "Step 4", "description": "Fry the eggs separately."}, {"title": "Step 5", "description": "Prepare or reheat the garlic fried rice."}, {"title": "Step 6", "description": "Plate the sardines, rice, and egg together."}, {"title": "Step 7", "description": "Serve hot."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Lugaw', 'Breakfast', '', 'Easy', '', '1 person', '300 kcal', 4294964192, '[{"name": "white rice", "description": "1 cup"}, {"name": "chicken broth or water", "description": "7 cups"}, {"name": "1 onion, chopped", "description": ""}, {"name": "garlic, minced", "description": "4 cloves"}, {"name": "1 thumb-sized ginger, sliced", "description": ""}, {"name": "fish sauce Servings: 1 person", "description": "2 tbsp"}, {"name": "cooking oil", "description": "2 tbsp"}, {"name": "Fried garlic, chopped spring onions, and boiled eggs for garnish", "description": ""}]'::jsonb, '[{"title": "Step 1", "description": "Heat oil and sauté the garlic, onion, and ginger until fragrant."}, {"title": "Step 2", "description": "Add the rice and stir for 2 minutes."}, {"title": "Step 3", "description": "Pour in the chicken broth or water and bring to a boil."}, {"title": "Step 4", "description": "Reduce the heat and simmer for 30–40 minutes, stirring occasionally until the rice breaks down into a creamy porridge."}, {"title": "Step 5", "description": "Stir in the fish sauce and adjust the seasoning."}, {"title": "Step 6", "description": "Ladle the lugaw into serving bowls."}, {"title": "Step 7", "description": "Garnish with fried garlic, spring onions, and boiled eggs before serving."}]'::jsonb);
