INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Chicken Tocino Silog', 'Breakfast', '', 'Easy', '', '1 person', '300 kcal', 4294964192, '[{"name": "chicken tocino", "description": "57g"}, {"name": "garlic fried rice", "description": "1/3 cup"}, {"name": "1 egg", "description": ""}, {"name": "cooking oil", "description": "1/3 tsp"}]'::jsonb, '[{"title": "Step 1", "description": "Place the chicken tocino in a pan with a small amount of water."}, {"title": "Step 2", "description": "Cook until the water evaporates."}, {"title": "Step 3", "description": "Add the oil and fry until lightly caramelized."}, {"title": "Step 4", "description": "Fry the eggs separately."}, {"title": "Step 5", "description": "Prepare the garlic fried rice."}, {"title": "Step 6", "description": "Arrange the chicken tocino, rice, and egg on a plate."}, {"title": "Step 7", "description": "Serve hot."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Tortang Talong with Garlic Rice', 'Breakfast', '', 'Easy', '', '1 person', '300 kcal', 4294964192, '[{"name": "arge eggplant", "description": "1 l"}, {"name": "1 egg, beaten", "description": ""}, {"name": "garlic, minced", "description": "1 clove"}, {"name": "Salt and ground black pepper to taste", "description": ""}, {"name": "cooking oil", "description": "2/3 tsp"}, {"name": "garlic fried rice", "description": "1/3 cup"}]'::jsonb, '[{"title": "Step 1", "description": "Grill the eggplants until the skin is charred and the flesh is tender."}, {"title": "Step 2", "description": "Peel off the skin while keeping the stem intact."}, {"title": "Step 3", "description": "Flatten each eggplant gently with a fork."}, {"title": "Step 4", "description": "Season with salt and pepper, then dip in the beaten eggs."}, {"title": "Step 5", "description": "Heat the oil and fry each eggplant until golden brown on both sides."}, {"title": "Step 6", "description": "Prepare or reheat the garlic fried rice."}, {"title": "Step 7", "description": "Serve hot with garlic rice and banana ketchup."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Beef Tapa with Garlic Rice and Atchara', 'Breakfast', '', 'Easy', '', '1 person', '300 kcal', 4294964192, '[{"name": "beef sirloin, thinly sliced", "description": "57g"}, {"name": "soy sauce", "description": "1/3 tsp"}, {"name": "calamansi juice", "description": "2/3 tsp"}, {"name": "brown sugar", "description": "1/3 tsp"}, {"name": "garlic, minced", "description": "1-1 clove"}, {"name": "ground black pepper", "description": "1/6 tsp"}, {"name": "cooking oil", "description": "2/3 tsp"}, {"name": "garlic fried rice", "description": "1/3 cup"}, {"name": "1 egg", "description": ""}, {"name": "Atchara for serving", "description": ""}]'::jsonb, '[{"title": "Step 1", "description": "Marinate the beef with soy sauce, calamansi juice, brown sugar, garlic, and black pepper for at least 4 hours."}, {"title": "Step 2", "description": "Heat the cooking oil in a frying pan over medium heat."}, {"title": "Step 3", "description": "Fry the marinated beef until browned and fully cooked."}, {"title": "Step 4", "description": "Fry the eggs to your preferred doneness."}, {"title": "Step 5", "description": "Prepare or reheat the garlic fried rice."}, {"title": "Step 6", "description": "Arrange the beef tapa, garlic rice, and fried egg on a serving plate."}, {"title": "Step 7", "description": "Serve with atchara on the side."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Pork Steak Silog', 'Breakfast', '', 'Easy', '', '1 person', 'approximately 600 kcal per serving', 4294964192, '[{"name": "pork chops", "description": "57g"}, {"name": "soy sauce", "description": "1/3 tsp"}, {"name": "calamansi juice", "description": "1/3 tbsp"}, {"name": "1/3 onion, sliced into rings", "description": ""}, {"name": "garlic, minced", "description": "1-1 clove"}, {"name": "cooking oil", "description": "2/3 tsp"}, {"name": "garlic fried rice", "description": "1/3 cup"}, {"name": "1 egg", "description": ""}]'::jsonb, '[{"title": "Step 1", "description": "Marinate the pork in soy sauce, calamansi juice, and garlic for at least 1 hour."}, {"title": "Step 2", "description": "Heat the oil and fry the pork until cooked through."}, {"title": "Step 3", "description": "Remove the pork and sauté the onion rings until tender."}, {"title": "Step 4", "description": "Return the pork to the pan and cook for another 2 minutes."}, {"title": "Step 5", "description": "Fry the eggs separately."}, {"title": "Step 6", "description": "Prepare the garlic fried rice."}, {"title": "Step 7", "description": "Serve the pork steak with garlic rice and fried egg."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Ginisang Corned Beef with Potato', 'Breakfast', '', 'Easy', '', '1 person', '300 kcal', 4294964192, '[{"name": "corned beef", "description": "1/2 can"}, {"name": "1 medium potato, diced", "description": ""}, {"name": "1/3 onion, chopped", "description": ""}, {"name": "garlic, minced", "description": "1 clove"}, {"name": "cooking oil", "description": "2/3 tsp"}, {"name": "Salt and pepper to taste", "description": ""}, {"name": "steamed rice", "description": "1/3 cup"}]'::jsonb, '[{"title": "Step 1", "description": "Heat oil in a frying pan."}, {"title": "Step 2", "description": "Fry the diced potatoes until lightly browned."}, {"title": "Step 3", "description": "Add the garlic and onion and sauté until fragrant."}, {"title": "Step 4", "description": "Stir in the corned beef and cook for 5–7 minutes."}, {"title": "Step 5", "description": "Season with salt and pepper."}, {"title": "Step 6", "description": "Prepare warm rice."}, {"title": "Step 7", "description": "Serve hot with rice."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Fried Galunggong Silog', 'Breakfast', '', 'Easy', '', '1 person', '300 kcal', 4294964192, '[{"name": "1 whole galunggong, cleaned", "description": ""}, {"name": "Salt and pepper to taste", "description": ""}, {"name": "cooking oil", "description": "2/3 tsp"}, {"name": "garlic fried rice", "description": "1/3 cup"}, {"name": "1 egg", "description": ""}]'::jsonb, '[{"title": "Step 1", "description": "Season the fish with salt and pepper."}, {"title": "Step 2", "description": "Heat the oil in a frying pan."}, {"title": "Step 3", "description": "Fry the fish until crispy on both sides."}, {"title": "Step 4", "description": "Remove and drain on paper towels."}, {"title": "Step 5", "description": "Fry the eggs."}, {"title": "Step 6", "description": "Prepare the garlic fried rice."}, {"title": "Step 7", "description": "Serve with vinegar and sliced tomatoes."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Ginisang Monggo with Rice', 'Breakfast', '', 'Easy', '', '1 person', 'approximately 600 kcal per serving', 4294964192, '[{"name": "mung beans", "description": "1/1 cup (monggo), cooked"}, {"name": "1/3 onion, chopped", "description": ""}, {"name": "garlic, minced", "description": "1 clove"}, {"name": "1 tomato, chopped", "description": ""}, {"name": "spinach or malunggay leaves", "description": "1/1 cup"}, {"name": "cooking oil", "description": "2/3 tsp"}, {"name": "Salt and pepper to taste", "description": ""}, {"name": "steamed rice", "description": "1/3 cup"}]'::jsonb, '[{"title": "Step 1", "description": "Heat oil and sauté the garlic, onion, and tomatoes."}, {"title": "Step 2", "description": "Add the cooked mung beans and stir well."}, {"title": "Step 3", "description": "Season with salt and pepper."}, {"title": "Step 4", "description": "Simmer for 5 minutes."}, {"title": "Step 5", "description": "Add the spinach or malunggay leaves."}, {"title": "Step 6", "description": "Cook for another 2 minutes."}, {"title": "Step 7", "description": "Serve hot with steamed rice."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Sardines Omelet', 'Breakfast', '', 'Easy', '', '1 person', '300 kcal', 4294964192, '[{"name": "sardines in tomato sauce", "description": "1/2 can"}, {"name": "2 eggs", "description": ""}, {"name": "1/3 onion, chopped", "description": ""}, {"name": "1 tomato, chopped", "description": ""}, {"name": "cooking oil", "description": "2/3 tsp"}, {"name": "Salt and pepper to taste", "description": ""}]'::jsonb, '[{"title": "Step 1", "description": "Beat the eggs in a bowl and season with salt and pepper."}, {"title": "Step 2", "description": "Mix in the sardines, onion, and tomato."}, {"title": "Step 3", "description": "Heat oil in a non-stick pan."}, {"title": "Step 4", "description": "Pour the egg mixture into the pan."}, {"title": "Step 5", "description": "Cook until the bottom is set."}, {"title": "Step 6", "description": "Flip carefully and cook the other side until golden. Servings: 1 person"}, {"title": "Step 7", "description": "Serve hot with garlic rice."}, {"title": "Step 8", "description": "Calories: approximately 600 kcal per serving"}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Fried Rice with Salted Egg and Tomatoes', 'Breakfast', '', 'Easy', '', '1 person', '300 kcal', 4294964192, '[{"name": "cooked rice", "description": "1/3 cup"}, {"name": "garlic, minced", "description": "1-1 clove"}, {"name": "1 salted egg, chopped", "description": ""}, {"name": "1 tomato, diced", "description": ""}, {"name": "cooking oil", "description": "2/3 tsp"}, {"name": "1 spring onion, chopped", "description": ""}, {"name": "Ground black pepper to taste", "description": ""}]'::jsonb, '[{"title": "Step 1", "description": "Heat the cooking oil and sauté the garlic until golden."}, {"title": "Step 2", "description": "Add the cooked rice and stir-fry for 3–5 minutes."}, {"title": "Step 3", "description": "Mix in the chopped salted eggs. Servings: 1 person"}, {"title": "Step 4", "description": "Add the diced tomatoes and spring onions."}, {"title": "Step 5", "description": "Calories: approximately 600 kcal per serving"}, {"title": "Step 6", "description": "Season with black pepper."}, {"title": "Step 7", "description": "Stir until everything is evenly combined."}, {"title": "Step 8", "description": "Serve warm as a complete breakfast or alongside grilled meat or fish."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Chorizosilog', 'Breakfast', '', 'Easy', '', '1 person', '300 kcal', 4294964192, '[{"name": "Vigan longganisa", "description": "2.7 pieces (chorizo)"}, {"name": "garlic fried rice", "description": "1/3 cup"}, {"name": "1 egg", "description": ""}, {"name": "cooking oil", "description": "1/3 tsp"}, {"name": "Vinegar for dipping", "description": ""}]'::jsonb, '[{"title": "Step 1", "description": "Place the Vigan longganisa in a frying pan with ¼ cup water."}, {"title": "Step 2", "description": "Cover and cook until the water evaporates. Servings: 1 person"}, {"title": "Step 3", "description": "Add the cooking oil and fry until browned on all sides."}, {"title": "Step 4", "description": "Calories: approximately 600 kcal per serving"}, {"title": "Step 5", "description": "Fry the eggs to your preferred doneness."}, {"title": "Step 6", "description": "Prepare or reheat the garlic fried rice."}, {"title": "Step 7", "description": "Arrange the longganisa, garlic rice, and egg on a serving plate."}, {"title": "Step 8", "description": "Serve hot with vinegar."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Daing na Bangus Silog', 'Breakfast', '', 'Easy', '', '1 person', '300 kcal', 4294964192, '[{"name": "1 marinated boneless bangus", "description": ""}, {"name": "cooking oil", "description": "2/3 tsp"}, {"name": "garlic fried rice", "description": "1/3 cup"}, {"name": "1 egg", "description": ""}, {"name": "Vinegar for dipping", "description": ""}]'::jsonb, '[{"title": "Step 1", "description": "Heat the cooking oil over medium heat."}, {"title": "Step 2", "description": "Fry the marinated bangus until golden brown on both sides."}, {"title": "Step 3", "description": "Remove and drain excess oil. Servings: 1 person"}, {"title": "Step 4", "description": "Fry the eggs separately."}, {"title": "Step 5", "description": "Calories: approximately 600 kcal per serving"}, {"title": "Step 6", "description": "Prepare the garlic fried rice."}, {"title": "Step 7", "description": "Arrange the fish, garlic rice, and egg on a serving plate."}, {"title": "Step 8", "description": "Serve with vinegar and sliced tomatoes."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Ginisang Itlog at Kamatis', 'Breakfast', '', 'Easy', '', '1 person', '300 kcal', 4294964192, '[{"name": "4 eggs", "description": ""}, {"name": "2 ripe tomatoes, chopped", "description": ""}, {"name": "1 onion, chopped", "description": ""}, {"name": "garlic, minced", "description": "3 cloves"}, {"name": "cooking oil", "description": "2 tbsp"}, {"name": "Salt and ground black pepper to taste", "description": ""}, {"name": "steamed rice", "description": "3 cups"}, {"name": "Heat the cooking oil in a frying pan.", "description": ""}, {"name": "Sauté the garlic and onion until fragrant.", "description": ""}, {"name": "Add the chopped tomatoes and cook until softened.", "description": ""}, {"name": "Beat the eggs and pour them into the pan.", "description": ""}, {"name": "Stir gently until the eggs are fully cooked.", "description": ""}, {"name": "Season with salt and pepper.", "description": ""}, {"name": "Serve hot with steamed rice.", "description": ""}, {"name": "Use ripe tomatoes for a sweeter flavor.", "description": ""}, {"name": "Cook the eggs over low heat for a softer texture.", "description": ""}, {"name": "Avoid overcooking the eggs.", "description": ""}, {"name": "Garnish with chopped spring onions if desired.", "description": ""}, {"name": "Region: Cebu Category: Breakfast Difficulty: Easy Servings: 1 person", "description": ""}, {"name": "A popular Visayan breakfast featuring crispy fried danggit served with garlic rice, fried egg, and spiced vinegar.", "description": ""}, {"name": "Ingredients", "description": ""}, {"name": "dried danggit", "description": "1 pieces"}, {"name": "cooking oil", "description": "2/3 tsp"}, {"name": "garlic fried rice", "description": "1/3 cup"}, {"name": "1 egg", "description": ""}, {"name": "Spiced vinegar for dipping", "description": ""}]'::jsonb, '[{"title": "Step 1", "description": "Quickly rinse the danggit and pat dry."}, {"title": "Step 2", "description": "Heat the oil over medium heat. Servings: 1 person"}, {"title": "Step 3", "description": "Fry the danggit until crispy."}, {"title": "Step 4", "description": "Calories: approximately 600 kcal per serving"}, {"title": "Step 5", "description": "Fry the eggs separately."}, {"title": "Step 6", "description": "Prepare the garlic fried rice."}, {"title": "Step 7", "description": "Arrange everything on a serving plate."}, {"title": "Step 8", "description": "Serve with spiced vinegar."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Chicken Pastil', 'Breakfast', '', 'Medium', '', '1 person', '300 kcal', 4294964192, '[{"name": "chicken breast", "description": "500g"}, {"name": "1 onion, chopped", "description": ""}, {"name": "garlic, minced", "description": "4 cloves"}, {"name": "1 thumb-sized ginger, minced", "description": ""}, {"name": "soy sauce", "description": "2 tbsp"}, {"name": "cooking oil", "description": "2 tbsp"}, {"name": "steamed rice", "description": "3 cups"}, {"name": "Banana leaves (optional)", "description": ""}, {"name": "Boil the chicken until fully cooked, then shred it.", "description": ""}, {"name": "Heat oil and sauté the garlic, onion, and ginger.", "description": ""}, {"name": "Add the shredded chicken and soy sauce.", "description": ""}, {"name": "Cook for 5–7 minutes while stirring.", "description": ""}, {"name": "Prepare warm steamed rice.", "description": ""}, {"name": "Serve the chicken over the rice or wrap both in banana leaves.", "description": ""}, {"name": "Enjoy while hot.", "description": ""}, {"name": "Simmer the chicken instead of overboiling to keep it moist.", "description": ""}, {"name": "Banana leaves add traditional aroma.", "description": ""}, {"name": "Add chili flakes for extra heat.", "description": ""}, {"name": "Serve with hard-boiled eggs if desired.", "description": ""}, {"name": "Region: Nationwide Category: Breakfast Difficulty: Easy Servings: 1 person", "description": ""}, {"name": "A healthy Filipino breakfast made with bitter melon sautéed with garlic, onions, tomatoes, and scrambled eggs. It is rich in vitamins and commonly served with rice.", "description": ""}, {"name": "Ingredients", "description": ""}, {"name": "2 medium ampalaya, thinly sliced", "description": ""}, {"name": "3 eggs", "description": ""}, {"name": "1 onion, chopped", "description": ""}, {"name": "2 tomatoes, chopped", "description": ""}, {"name": "garlic, minced", "description": "3 cloves"}, {"name": "cooking oil", "description": "2 tbsp"}, {"name": "Salt and pepper to taste Servings: 1 person", "description": ""}]'::jsonb, '[{"title": "Step 1", "description": "Calories: approximately 600 kcal per serving"}, {"title": "Step 2", "description": "Sprinkle salt over the sliced ampalaya and let it sit for 10 minutes, then rinse and drain."}, {"title": "Step 3", "description": "Heat oil and sauté the garlic, onion, and tomatoes."}, {"title": "Step 4", "description": "Add the ampalaya and cook for 3–4 minutes."}, {"title": "Step 5", "description": "Beat the eggs and pour them into the pan."}, {"title": "Step 6", "description": "Stir gently until the eggs are cooked."}, {"title": "Step 7", "description": "Season with salt and pepper."}, {"title": "Step 8", "description": "Serve hot with steamed rice."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Beef Giniling with Rice', 'Breakfast', '', 'Easy', '', '1 person', '300 kcal', 4294964192, '[{"name": "ground beef", "description": "500g"}, {"name": "1 onion, chopped", "description": ""}, {"name": "garlic, minced", "description": "4 cloves"}, {"name": "2 tomatoes, chopped", "description": ""}, {"name": "½ cup diced carrots", "description": ""}, {"name": "½ cup green peas Servings: 1 person", "description": ""}, {"name": "soy sauce", "description": "2 tbsp"}, {"name": "cooking oil", "description": "2 tbsp"}, {"name": "steamed rice", "description": "3 cups"}, {"name": "3 eggs", "description": ""}]'::jsonb, '[{"title": "Step 1", "description": "Heat oil and sauté the garlic, onion, and tomatoes until softened."}, {"title": "Step 2", "description": "Add the ground beef and cook until browned."}, {"title": "Step 3", "description": "Stir in the carrots, green peas, and soy sauce."}, {"title": "Step 4", "description": "Simmer for 8–10 minutes until the vegetables are tender."}, {"title": "Step 5", "description": "Fry the eggs separately."}, {"title": "Step 6", "description": "Serve the beef giniling with steamed rice and a fried egg."}, {"title": "Step 7", "description": "Enjoy while hot."}]'::jsonb);
