INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Pork Giniling Silog', 'Breakfast', '', 'Easy', '', '1 person', '300 kcal', 4294964192, '[{"name": "ground pork", "description": "500g"}, {"name": "1 onion, chopped", "description": ""}, {"name": "garlic, minced Servings: 1 person", "description": "3 cloves"}, {"name": "2 tomatoes, chopped", "description": ""}, {"name": "½ cup diced carrots", "description": ""}, {"name": "½ cup green peas", "description": ""}, {"name": "soy sauce", "description": "2 tbsp"}, {"name": "cooking oil", "description": "2 tbsp"}, {"name": "garlic fried rice", "description": "3 cups"}, {"name": "3 eggs", "description": ""}]'::jsonb, '[{"title": "Step 1", "description": "Heat oil and sauté the garlic, onion, and tomatoes."}, {"title": "Step 2", "description": "Add the ground pork and cook until browned."}, {"title": "Step 3", "description": "Stir in the carrots, peas, and soy sauce."}, {"title": "Step 4", "description": "Simmer until the vegetables are tender."}, {"title": "Step 5", "description": "Fry the eggs separately."}, {"title": "Step 6", "description": "Prepare the garlic fried rice."}, {"title": "Step 7", "description": "Serve hot."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Chicken Omelet with Garlic Rice', 'Breakfast', '', 'Easy', '', '1 person', '300 kcal', 4294964192, '[{"name": "cooked shredded chicken", "description": "2 cups"}, {"name": "4 eggs Servings: 1 person", "description": ""}, {"name": "1 onion, chopped", "description": ""}, {"name": "½ bell pepper, diced", "description": ""}, {"name": "cooking oil", "description": "2 tbsp"}, {"name": "Salt and pepper to taste", "description": ""}, {"name": "garlic fried rice", "description": "3 cups"}]'::jsonb, '[{"title": "Step 1", "description": "Beat the eggs and season with salt and pepper."}, {"title": "Step 2", "description": "Sauté the onion and bell pepper until soft."}, {"title": "Step 3", "description": "Add the shredded chicken and cook for 2 minutes."}, {"title": "Step 4", "description": "Pour in the beaten eggs."}, {"title": "Step 5", "description": "Cook until set, then fold the omelet in half."}, {"title": "Step 6", "description": "Prepare the garlic fried rice."}, {"title": "Step 7", "description": "Serve immediately."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Pancit Canton', 'Breakfast', '', 'Easy', '', '1 person', '300 kcal', 4294964192, '[{"name": "pancit canton noodles", "description": "28g"}, {"name": "chicken breast, sliced", "description": "33g"}, {"name": "cabbage, shredded, shredded", "description": "1/1 cup"}, {"name": "1/3 carrot, julienned", "description": ""}, {"name": "garlic, minced", "description": "1 clove"}, {"name": "1/3 onion, sliced", "description": ""}, {"name": "soy sauce", "description": "2/3 tsp"}, {"name": "cooking oil", "description": "2/3 tsp"}, {"name": "1 egg", "description": ""}, {"name": "pandesal", "description": "2/3 pieces"}]'::jsonb, '[{"title": "Step 1", "description": "Cook the pancit canton noodles according to the package directions and drain."}, {"title": "Step 2", "description": "Heat the oil and sauté the garlic and onion until fragrant."}, {"title": "Step 3", "description": "Add the chicken and cook until lightly browned."}, {"title": "Step 4", "description": "Stir in the cabbage and carrots, then cook until tender."}, {"title": "Step 5", "description": "Add the noodles and soy sauce, tossing until evenly coated."}, {"title": "Step 6", "description": "Fry the eggs separately and toast the pandesal."}, {"title": "Step 7", "description": "Serve the pancit canton with a fried egg and toasted pandesal."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Tortang Dilis', 'Breakfast', '', 'Easy', '', '1 person', '300 kcal', 4294964192, '[{"name": "dried dilis", "description": "1 cup (anchovies)"}, {"name": "4 eggs", "description": ""}, {"name": "1 onion, chopped", "description": ""}, {"name": "1 tomato, chopped", "description": ""}, {"name": "cooking oil", "description": "2 tbsp"}, {"name": "Salt and pepper to taste", "description": ""}, {"name": "steamed rice", "description": "3 cups"}]'::jsonb, '[{"title": "Step 1", "description": "Rinse the dried anchovies quickly and pat dry."}, {"title": "Step 2", "description": "Beat the eggs and mix in the onion and tomato."}, {"title": "Step 3", "description": "Stir in the dried anchovies."}, {"title": "Step 4", "description": "Heat the oil in a non-stick pan."}, {"title": "Step 5", "description": "Pour in the egg mixture and cook until golden on the bottom."}, {"title": "Step 6", "description": "Flip carefully and cook the other side until fully set."}, {"title": "Step 7", "description": "Serve hot with steamed rice."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Sinigang na Baboy', 'Soup/Stew', '', 'Medium', '', '1 person', 'approximately 600 kcal per serving', 4294964192, '[{"name": "pork ribs, cut into serving pieces", "description": "150g"}, {"name": "1/2 medium tomato, quartered", "description": ""}, {"name": "1/4 medium onion, quartered", "description": ""}, {"name": "siling haba", "description": "1/2 pc"}, {"name": "1/4 medium radish, sliced", "description": ""}, {"name": "1/4 medium eggplant, sliced", "description": ""}, {"name": "1/4 bundle kangkong, stems trimmed", "description": ""}, {"name": "sinigang mix or 30g fresh tamarind", "description": "10g"}, {"name": "water", "description": "500ml"}, {"name": "fish sauce, or to taste", "description": "1 tbsp"}]'::jsonb, '[{"title": "Step 1", "description": "In a large pot, bring 2 liters of water to a boil. Add pork ribs and blanch for 5 minutes. Discard water and rinse pork."}, {"title": "Step 2", "description": "Return pork to pot with fresh 2 liters water. Add tomatoes and onion. Boil then simmer for 45-60 minutes until pork is fork-tender."}, {"title": "Step 3", "description": "Skim scum regularly for a clear broth."}, {"title": "Step 4", "description": "Add tamarind mix or strained fresh tamarind juice. Stir and taste."}, {"title": "Step 5", "description": "Add radish and eggplant. Simmer 5 minutes."}, {"title": "Step 6", "description": "Add siling haba and kangkong. Cook 2 minutes more."}, {"title": "Step 7", "description": "Season with fish sauce. Serve hot with steamed rice."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Adobong Manok', 'Braised', '', 'Easy', '', '1 person', 'approximately 650 kcal per serving', 4294964192, '[{"name": "chicken, preferably bone-in thigh or drumstick", "description": "150g"}, {"name": "vinegar", "description": "2 tbsp"}, {"name": "soy sauce", "description": "1 tbsp"}, {"name": "garlic, crushed", "description": "3 cloves"}, {"name": "bay leaf", "description": "1 pc"}, {"name": "whole black peppercorns", "description": "1/4 tsp"}, {"name": "water", "description": "1/4 cup"}, {"name": "cooking oil", "description": "1 tsp"}]'::jsonb, '[{"title": "Step 1", "description": "Combine chicken, vinegar, soy sauce, garlic, bay leaves, and peppercorns in a pot. Marinate 30 minutes to 1 hour."}, {"title": "Step 2", "description": "Add water. Bring to a boil over medium-high heat without stirring."}, {"title": "Step 3", "description": "Once boiling, lower heat and simmer for 25-30 minutes until chicken is tender."}, {"title": "Step 4", "description": "Remove chicken and pan-fry in hot oil until golden brown."}, {"title": "Step 5", "description": "Return to pot and reduce remaining sauce until thick and glossy."}, {"title": "Step 6", "description": "Serve with steamed rice."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Kare-Kare', 'Soup/Stew', '', 'Hard', '', '1 person', 'approximately 1050 kcal per serving', 4294964192, '[{"name": "oxtail", "description": "150g"}, {"name": "banana blossom", "description": "100g"}, {"name": "1/4 medium eggplant", "description": ""}, {"name": "sitaw", "description": "60g"}, {"name": "peanut butter", "description": "1 tbsp"}, {"name": "ground toasted peanuts", "description": "1 tbsp"}, {"name": "annatto powder dissolved in 1/4 cup water", "description": "1 tsp"}, {"name": "1/4 medium onion", "description": ""}, {"name": "garlic", "description": "1 clove"}, {"name": "cooking oil", "description": "1 tsp"}, {"name": "fish sauce", "description": "1 tsp"}, {"name": "Salt to taste", "description": ""}, {"name": "bagoong alamang, for serving", "description": "1 tbsp"}]'::jsonb, '[{"title": "Step 1", "description": "Pressure cook oxtail with enough water for 45 minutes or boil for 2-3 hours until very tender. Reserve broth (at least 4 cups)."}, {"title": "Step 2", "description": "In a large pot, sauté garlic and onion in oil until soft."}, {"title": "Step 3", "description": "Add the annatto water; stir and cook 2 minutes."}, {"title": "Step 4", "description": "Add peanut butter and ground peanuts. Stir well."}, {"title": "Step 5", "description": "Pour in reserved oxtail broth. Bring to simmer."}, {"title": "Step 6", "description": "Add oxtail. Simmer 10 minutes."}, {"title": "Step 7", "description": "Add eggplant, banana blossom, and sitaw. Cook until vegetables are tender, about 8-10 minutes."}, {"title": "Step 8", "description": "Season with fish sauce and salt. Sauce should be thick and creamy."}, {"title": "Step 9", "description": "Serve with a generous side of sautéed bagoong alamang."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Lechon Kawali', 'Grilled/Fried', '', 'Medium', '', '1 person', 'approximately 1420 kcal per serving', 4294964192, '[{"name": "pork belly slab", "description": "180g"}, {"name": "salt", "description": "1/2 tsp"}, {"name": "black pepper", "description": "1/4 tsp"}, {"name": "bay leaf", "description": "1 pc"}, {"name": "garlic, crushed", "description": "2 cloves"}, {"name": "Water for boiling", "description": ""}, {"name": "Oil for deep-frying", "description": ""}]'::jsonb, '[{"title": "Step 1", "description": "Place pork belly in a pot. Cover with water. Add salt, pepper, bay leaves, and garlic."}, {"title": "Step 2", "description": "Boil then simmer for 45-60 minutes until pork is very tender (fork goes through easily)."}, {"title": "Step 3", "description": "Remove pork; cool to room temperature."}, {"title": "Step 4", "description": "Refrigerate uncovered overnight (or at least 4 hours) — this dries the skin for maximum crispiness."}, {"title": "Step 5", "description": "Heat oil to 180°C in a deep pot or kawali."}, {"title": "Step 6", "description": "Carefully lower pork into hot oil. Fry 15-20 minutes until deep golden and very crispy."}, {"title": "Step 7", "description": "Drain on wire rack (not paper towels — steam makes skin soggy)."}, {"title": "Step 8", "description": "Rest 5 minutes before chopping. Serve with liver sauce or spiced vinegar."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Tinolang Manok', 'Soup/Stew', '', 'Easy', '', '1 person', 'approximately 520 kcal per serving', 4294964192, '[{"name": "chicken pieces", "description": "150g"}, {"name": "green papaya, peeled and sliced", "description": "150g"}, {"name": "malunggay leaves", "description": "1/2 cup"}, {"name": "1-inch ginger, julienned", "description": ""}, {"name": "1/4 medium onion, sliced", "description": ""}, {"name": "garlic, minced", "description": "1 clove"}, {"name": "fish sauce", "description": "1 tbsp"}, {"name": "water", "description": "500ml"}, {"name": "cooking oil", "description": "1 tsp"}]'::jsonb, '[{"title": "Step 1", "description": "Heat oil in pot over medium heat. Sauté ginger until fragrant, about 1 minute."}, {"title": "Step 2", "description": "Add garlic and onion; cook until soft."}, {"title": "Step 3", "description": "Add chicken pieces. Cook, turning, until lightly browned on all sides."}, {"title": "Step 4", "description": "Pour in water. Bring to a boil; skim scum."}, {"title": "Step 5", "description": "Add green papaya. Simmer 15-20 minutes until papaya and chicken are tender."}, {"title": "Step 6", "description": "Season with fish sauce."}, {"title": "Step 7", "description": "Add malunggay leaves. Cook 1 minute more."}, {"title": "Step 8", "description": "Serve hot with rice."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Bistek Tagalog', 'Braised', '', 'Easy', '', '1 person', 'approximately 1030 kcal per serving', 4294964192, '[{"name": "beef sirloin or round, thinly sliced", "description": "150g"}, {"name": "1 1/2 tbsp calamansi juice", "description": ""}, {"name": "soy sauce", "description": "1 tbsp"}, {"name": "1/2 medium onion, sliced into rings", "description": ""}, {"name": "garlic, minced", "description": "1 clove"}, {"name": "black pepper", "description": "1/8 tsp"}, {"name": "cooking oil", "description": "1 tsp"}, {"name": "Salt to taste", "description": ""}]'::jsonb, '[{"title": "Step 1", "description": "Marinate beef in calamansi juice, soy sauce, garlic, and black pepper for at least 30 minutes."}, {"title": "Step 2", "description": "Heat oil in pan over high heat. Sear beef slices quickly, about 1 minute per side. Remove and set aside."}, {"title": "Step 3", "description": "In same pan, cook onion rings until slightly softened and lightly caramelized."}, {"title": "Step 4", "description": "Return beef to pan with marinade. Simmer 2-3 minutes until sauce slightly thickens."}, {"title": "Step 5", "description": "Taste and adjust — add more calamansi for sourness, soy for saltiness."}, {"title": "Step 6", "description": "Serve over steamed rice, topped with onion rings."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Pork Dinuguan', 'Soup/Stew', '', 'Medium', '', '1 person', 'approximately 1850 kcal per serving', 4294964192, '[{"name": "pork shoulder, cubed", "description": "150g"}, {"name": "pork intestine, cleaned and cut", "description": "75g"}, {"name": "fresh pork blood", "description": "1/4 cup"}, {"name": "1 1/2 tbsp vinegar", "description": ""}, {"name": "garlic", "description": "1 clove"}, {"name": "1/4 medium onion", "description": ""}, {"name": "siling haba", "description": "1 pc"}, {"name": "cooking oil", "description": "1 tsp"}, {"name": "Fish sauce and salt to taste", "description": ""}]'::jsonb, '[{"title": "Step 1", "description": "Boil pork intestines in water with garlic and vinegar for 30 minutes until tender. Drain and cut."}, {"title": "Step 2", "description": "In a pot, heat oil and sauté garlic and onion until fragrant."}, {"title": "Step 3", "description": "Add pork shoulder; cook until browned."}, {"title": "Step 4", "description": "Add intestines; stir."}, {"title": "Step 5", "description": "Pour in pork blood. Stir constantly while bringing to a simmer to prevent lumps."}, {"title": "Step 6", "description": "Add vinegar; do not stir for 2 minutes (let it cook off)."}, {"title": "Step 7", "description": "Add siling haba. Simmer 15-20 minutes until sauce thickens."}, {"title": "Step 8", "description": "Season with fish sauce and salt. Serve with puto or steamed rice."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Paksiw na Isda', 'Braised', '', 'Easy', '', '1 person', 'approximately 800 kcal per serving', 4294964192, '[{"name": "bangus or tilapia, sliced", "description": "150g"}, {"name": "white vinegar", "description": "2 tbsp"}, {"name": "water", "description": "1/4 cup"}, {"name": "1-inch ginger, sliced", "description": ""}, {"name": "1/4 medium onion", "description": ""}, {"name": "garlic", "description": "1 clove"}, {"name": "whole peppercorns", "description": "1/4 tsp"}, {"name": "siling haba", "description": "1/2 pc"}, {"name": "cooking oil", "description": "1 tsp"}, {"name": "Salt or fish sauce to taste", "description": ""}]'::jsonb, '[{"title": "Step 1", "description": "Arrange ginger, garlic, and onion at the bottom of a pot."}, {"title": "Step 2", "description": "Layer fish on top."}, {"title": "Step 3", "description": "Pour vinegar and water over fish. Add peppercorns and siling haba."}, {"title": "Step 4", "description": "Do not stir. Bring to a boil over medium heat."}, {"title": "Step 5", "description": "Once boiling, lower heat. Simmer 15 minutes until fish is cooked and liquid slightly reduces."}, {"title": "Step 6", "description": "Drizzle cooking oil over the top."}, {"title": "Step 7", "description": "Season with salt or fish sauce. Serve hot."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Ginisang Ampalaya', 'Sautéed', '', 'Easy', '', '1 person', 'approximately 180 kcal per serving', 4294964192, '[{"name": "1/2 medium ampalaya, sliced", "description": ""}, {"name": "arge egg, beaten", "description": "1 l"}, {"name": "garlic, minced", "description": "2 cloves"}, {"name": "1/4 medium onion", "description": ""}, {"name": "1/2 medium tomato", "description": ""}, {"name": "bagoong alamang", "description": "1 tsp"}, {"name": "Salt and pepper", "description": ""}, {"name": "cooking oil", "description": "1 tsp"}]'::jsonb, '[{"title": "Step 1", "description": "Rub sliced ampalaya with 1 tbsp salt. Let sit 15 minutes. Squeeze firmly to remove bitter liquid. Rinse and drain."}, {"title": "Step 2", "description": "Heat oil in pan over medium heat. Sauté garlic until golden."}, {"title": "Step 3", "description": "Add onion and tomatoes; cook until soft."}, {"title": "Step 4", "description": "Add bagoong; stir and cook 1 minute."}, {"title": "Step 5", "description": "Add ampalaya. Stir-fry 3-5 minutes until tender-crisp."}, {"title": "Step 6", "description": "Pour beaten eggs over ampalaya; let set briefly then scramble gently."}, {"title": "Step 7", "description": "Season with salt and pepper. Serve immediately."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Bulalo', 'Soup/Stew', '', 'Hard', '', '1 person', 'approximately 650 kcal per serving', 4294964192, '[{"name": "beef shank with bone marrow", "description": "200g"}, {"name": "corn", "description": "1/2 pc"}, {"name": "1/8 small cabbage", "description": ""}, {"name": "1/4 bundle pechay", "description": ""}, {"name": "1/4 medium onion", "description": ""}, {"name": "whole peppercorns", "description": "1/4 tsp"}, {"name": "fish sauce", "description": "1 tbsp"}, {"name": "liter water", "description": "1 l"}]'::jsonb, '[{"title": "Step 1", "description": "Blanch beef shank in boiling water for 5 minutes. Discard water; rinse."}, {"title": "Step 2", "description": "Return beef to pot. Cover with fresh 3 liters water. Add onion and peppercorns."}, {"title": "Step 3", "description": "Bring to a boil; skim scum thoroughly."}, {"title": "Step 4", "description": "Simmer on low heat for 2.5-3 hours until beef is very tender and marrow is soft."}, {"title": "Step 5", "description": "Add corn. Cook 20 minutes."}, {"title": "Step 6", "description": "Add cabbage and pechay. Cook 5 minutes until tender."}, {"title": "Step 7", "description": "Season generously with fish sauce."}, {"title": "Step 8", "description": "Serve piping hot with corn, marrow, and all the vegetables."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Laing', 'Braised', '', 'Medium', '', '1 person', 'approximately 3900 kcal per serving', 4294964192, '[{"name": "dried taro leaves", "description": "50g"}, {"name": "pork belly", "description": "100g"}, {"name": "thin coconut milk", "description": "150ml"}, {"name": "coconut cream", "description": "75ml"}, {"name": "bagoong alamang", "description": "1 tbsp"}, {"name": "siling haba", "description": "1 pc"}, {"name": "siling labuyo", "description": "1 pc"}, {"name": "garlic", "description": "2 cloves"}, {"name": "1/4 medium onion", "description": ""}, {"name": "1/2-inch ginger", "description": ""}]'::jsonb, '[{"title": "Step 1", "description": "Layer dried taro leaves at the bottom of a wide pot. Do NOT wash them."}, {"title": "Step 2", "description": "Scatter garlic, onion, and ginger over the leaves."}, {"title": "Step 3", "description": "Place pork on top. Add bagoong and all chilis."}, {"title": "Step 4", "description": "Pour thin coconut milk over everything. Do NOT stir."}, {"title": "Step 5", "description": "Bring to a boil over medium heat. Do not stir."}, {"title": "Step 6", "description": "Lower heat; simmer uncovered 20-25 minutes until coconut milk is mostly absorbed."}, {"title": "Step 7", "description": "Gently pour thick coconut cream over the top. Stir once or twice only."}, {"title": "Step 8", "description": "Simmer 10-15 more minutes until cream reduces and oil separates."}, {"title": "Step 9", "description": "Taste and adjust with more bagoong if needed. Serve with rice."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Bicol Express', 'Braised', '', 'Easy', '', '1 person', 'approximately 4250 kcal per serving', 4294964192, '[{"name": "pork belly", "description": "150g"}, {"name": "coconut milk", "description": "150ml"}, {"name": "coconut cream", "description": "75ml"}, {"name": "siling haba", "description": "1 pc"}, {"name": "siling labuyo", "description": "1 pc"}, {"name": "bagoong alamang", "description": "1 tbsp"}, {"name": "garlic", "description": "2 cloves"}, {"name": "1/4 medium onion", "description": ""}, {"name": "cooking oil", "description": "1 tsp"}]'::jsonb, '[{"title": "Step 1", "description": "Heat oil; sauté garlic and onion until soft."}, {"title": "Step 2", "description": "Add pork belly. Cook until lightly browned."}, {"title": "Step 3", "description": "Add bagoong; stir and cook 2 minutes."}, {"title": "Step 4", "description": "Add all chilis. Stir."}, {"title": "Step 5", "description": "Pour coconut milk. Bring to a boil."}, {"title": "Step 6", "description": "Simmer 15-20 minutes, stirring occasionally."}, {"title": "Step 7", "description": "Add coconut cream. Reduce until sauce is thick and oil separates."}, {"title": "Step 8", "description": "Serve with lots of steamed rice."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Ginataang Kalabasa', 'Sautéed', '', 'Easy', '', '1 person', 'approximately 1750 kcal per serving', 4294964192, '[{"name": "kalabasa", "description": "150g"}, {"name": "sitaw", "description": "75g"}, {"name": "pork belly", "description": "75g"}, {"name": "shrimp", "description": "75g"}, {"name": "coconut milk", "description": "150ml"}, {"name": "garlic", "description": "1 clove"}, {"name": "1/4 medium onion", "description": ""}, {"name": "bagoong alamang", "description": "1 tsp"}, {"name": "Salt and pepper", "description": ""}, {"name": "cooking oil", "description": "1 tsp"}]'::jsonb, '[{"title": "Step 1", "description": "Heat oil; sauté garlic and onion."}, {"title": "Step 2", "description": "Add pork; cook until browned."}, {"title": "Step 3", "description": "Add shrimp; cook until pink."}, {"title": "Step 4", "description": "Add bagoong; stir 1 minute."}, {"title": "Step 5", "description": "Add kalabasa. Pour coconut milk over."}, {"title": "Step 6", "description": "Simmer 10 minutes until kalabasa starts to soften."}, {"title": "Step 7", "description": "Add sitaw. Cook 5 minutes more."}, {"title": "Step 8", "description": "Season with salt and pepper. Serve hot."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Pritong Bangus', 'Grilled/Fried', '', 'Easy', '', '1 person', 'approximately 500 kcal per serving', 4294964192, '[{"name": "1/4 whole bangus, cleaned and butterflied", "description": ""}, {"name": "garlic", "description": "1 clove"}, {"name": "calamansi juice", "description": "1 tbsp"}, {"name": "salt", "description": "1/4 tsp"}, {"name": "black pepper", "description": "1/8 tsp"}, {"name": "cooking oil", "description": "1 tbsp"}]'::jsonb, '[{"title": "Step 1", "description": "Score the flesh of the bangus with diagonal cuts 1 inch apart."}, {"title": "Step 2", "description": "Rub all over with garlic, calamansi juice, salt, and pepper. Marinate 15-30 minutes."}, {"title": "Step 3", "description": "Heat generous amount of oil in a large pan over medium-high heat."}, {"title": "Step 4", "description": "Fry bangus skin-side up first for 5-7 minutes until golden."}, {"title": "Step 5", "description": "Carefully flip; fry skin side 5-7 minutes until very crispy."}, {"title": "Step 6", "description": "Drain on wire rack. Serve immediately with tomato-onion salsa or spiced vinegar."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Escabeche', 'Sautéed', '', 'Medium', '', '1 person', 'approximately 620 kcal per serving', 4294964192, '[{"name": "fish, cleaned", "description": "150g"}, {"name": "vinegar", "description": "1 tbsp"}, {"name": "sugar", "description": "1 tsp"}, {"name": "1/4 medium carrot", "description": ""}, {"name": "1/4 red bell pepper", "description": ""}, {"name": "reen bell pepper", "description": "1/4 g"}, {"name": "1-inch ginger", "description": ""}, {"name": "1/4 medium onion", "description": ""}, {"name": "soy sauce", "description": "1 tsp"}, {"name": "water", "description": "2 tbsp"}, {"name": "cornstarch dissolved in 1 tbsp water", "description": "1 tsp"}, {"name": "Salt and pepper", "description": ""}, {"name": "oil for frying", "description": "2 tbsp"}]'::jsonb, '[{"title": "Step 1", "description": "Season fish with salt and pepper. Fry in hot oil until golden crispy. Drain; set on serving plate."}, {"title": "Step 2", "description": "In same pan with 2 tbsp oil, sauté ginger and onion."}, {"title": "Step 3", "description": "Add carrots and bell peppers; stir-fry 2 minutes."}, {"title": "Step 4", "description": "Add vinegar, soy sauce, sugar, and water. Bring to a simmer."}, {"title": "Step 5", "description": "Add cornstarch mixture; stir until sauce thickens."}, {"title": "Step 6", "description": "Taste — should be sweet, sour, and savory."}, {"title": "Step 7", "description": "Pour sauce over fried fish. Serve immediately."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Tokwa''t Baboy', 'Salad/Fresh', '', 'Easy', '', '1 person', 'approximately 1050 kcal per serving', 4294964192, '[{"name": "pork ears, cleaned", "description": "150g"}, {"name": "firm tokwa", "description": "100g"}, {"name": "vinegar", "description": "1 tbsp"}, {"name": "soy sauce", "description": "1 tsp"}, {"name": "calamansi juice", "description": "1 tsp"}, {"name": "sugar", "description": "1/2 tsp"}, {"name": "red onion", "description": "2 tbsp"}, {"name": "siling labuyo", "description": "1/2 pc"}, {"name": "garlic", "description": "1 clove"}, {"name": "oil for frying", "description": "1 tbsp"}]'::jsonb, '[{"title": "Step 1", "description": "Boil pork ears in water with garlic and peppercorns for 1 hour until very tender. Cool; slice thinly."}, {"title": "Step 2", "description": "Drain tokwa; press to remove excess moisture. Cube into 1-inch pieces."}, {"title": "Step 3", "description": "Fry tokwa in hot oil until golden and crispy on all sides. Drain."}, {"title": "Step 4", "description": "Make dressing: combine vinegar, soy sauce, calamansi juice, sugar, onion, chili, and garlic. Mix well."}, {"title": "Step 5", "description": "Combine pork ears and tokwa on a plate."}, {"title": "Step 6", "description": "Pour dressing over. Toss gently. Serve immediately."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Caldereta', 'Braised', '', 'Hard', '', '1 person', 'approximately 700 kcal per serving', 4294964192, '[{"name": "goat or beef", "description": "150g"}, {"name": "tomato sauce", "description": "100g"}, {"name": "liver spread", "description": "40g"}, {"name": "1/2 medium potato", "description": ""}, {"name": "1/2 medium carrot", "description": ""}, {"name": "1/4 red bell pepper", "description": ""}, {"name": "green olives", "description": "2 tbsp"}, {"name": "siling labuyo", "description": "1 pc"}, {"name": "1/4 medium onion", "description": ""}, {"name": "garlic", "description": "1 clove"}, {"name": "water or broth", "description": "1/4 cup"}, {"name": "oil", "description": "1 tsp"}, {"name": "Salt, pepper, and fish sauce to taste", "description": ""}]'::jsonb, '[{"title": "Step 1", "description": "Marinate meat in vinegar, garlic, and pepper for 1 hour if using goat."}, {"title": "Step 2", "description": "Brown meat in hot oil. Remove; set aside."}, {"title": "Step 3", "description": "Sauté garlic and onion. Add tomato sauce; cook 3 minutes."}, {"title": "Step 4", "description": "Add liver spread; stir until incorporated."}, {"title": "Step 5", "description": "Return meat. Add water. Simmer covered 1-1.5 hours until tender."}, {"title": "Step 6", "description": "Add potatoes and carrots. Cook 15 minutes."}, {"title": "Step 7", "description": "Add bell peppers, olives, and chilis."}, {"title": "Step 8", "description": "Season with salt, pepper, fish sauce."}, {"title": "Step 9", "description": "Simmer 5 more minutes. Serve with rice."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Afritada', 'Braised', '', 'Easy', '', '1 person', 'approximately 650 kcal per serving', 4294964192, '[{"name": "chicken pieces", "description": "150g"}, {"name": "tomato sauce", "description": "100g"}, {"name": "1/2 medium potato", "description": ""}, {"name": "1/2 medium carrot", "description": ""}, {"name": "1/4 red bell pepper", "description": ""}, {"name": "water", "description": "1/4 cup"}, {"name": "1/4 medium onion", "description": ""}, {"name": "garlic", "description": "1 clove"}, {"name": "soy sauce", "description": "1 tsp"}, {"name": "cooking oil", "description": "1 tsp"}, {"name": "Salt and pepper", "description": ""}]'::jsonb, '[{"title": "Step 1", "description": "Brown chicken in hot oil. Remove and set aside."}, {"title": "Step 2", "description": "Sauté garlic and onion in same pan."}, {"title": "Step 3", "description": "Add tomato sauce; cook 3 minutes."}, {"title": "Step 4", "description": "Add soy sauce and water. Return chicken."}, {"title": "Step 5", "description": "Simmer covered 20 minutes."}, {"title": "Step 6", "description": "Add potatoes and carrots. Cook 15 minutes."}, {"title": "Step 7", "description": "Add bell pepper. Cook 5 more minutes."}, {"title": "Step 8", "description": "Season with salt and pepper. Serve."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Pork Menudo', 'Sautéed', '', 'Medium', '', '1 person', 'approximately 1150 kcal per serving', 4294964192, '[{"name": "pork shoulder", "description": "150g"}, {"name": "pork liver", "description": "75g"}, {"name": "1/2 medium potato", "description": ""}, {"name": "1/2 medium carrot", "description": ""}, {"name": "tomato sauce", "description": "100g"}, {"name": "raisins", "description": "1 tbsp"}, {"name": "1/4 red bell pepper", "description": ""}, {"name": "1/4 medium onion", "description": ""}, {"name": "garlic", "description": "1 clove"}, {"name": "soy sauce", "description": "1 tsp"}, {"name": "water", "description": "2 tbsp"}, {"name": "cooking oil", "description": "1 tsp"}, {"name": "Salt and pepper", "description": ""}]'::jsonb, '[{"title": "Step 1", "description": "Heat oil; sauté garlic and onion."}, {"title": "Step 2", "description": "Add pork; cook until browned."}, {"title": "Step 3", "description": "Add soy sauce and cook 2 minutes."}, {"title": "Step 4", "description": "Add tomato sauce and water. Simmer 15 minutes."}, {"title": "Step 5", "description": "Add potatoes and carrots. Cook 12 minutes."}, {"title": "Step 6", "description": "Add liver; cook 3 minutes (don''t overcook)."}, {"title": "Step 7", "description": "Add bell pepper and raisins."}, {"title": "Step 8", "description": "Season and simmer 3 more minutes. Serve."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Chopsuey', 'Sautéed', '', 'Easy', '', '1 person', 'approximately 650 kcal per serving', 4294964192, '[{"name": "pork or chicken", "description": "100g"}, {"name": "shrimp", "description": "50g"}, {"name": "1/8 head cabbage", "description": ""}, {"name": "1/2 medium carrot", "description": ""}, {"name": "snap peas or Baguio beans", "description": "50g"}, {"name": "cauliflower", "description": "50g"}, {"name": "quail eggs, optional", "description": "2 pcs"}, {"name": "1/4 medium onion", "description": ""}, {"name": "garlic", "description": "1 clove"}, {"name": "oyster sauce", "description": "1 tbsp"}, {"name": "soy sauce", "description": "1 tsp"}, {"name": "broth", "description": "2 tbsp"}, {"name": "cornstarch dissolved in 1 tbsp water", "description": "1 tsp"}, {"name": "cooking oil", "description": "1 tsp"}]'::jsonb, '[{"title": "Step 1", "description": "Blanch hard vegetables (carrots, cauliflower) in salted water for 2 minutes. Drain."}, {"title": "Step 2", "description": "Heat oil; sauté garlic and onion."}, {"title": "Step 3", "description": "Add pork; cook until done. Add shrimp."}, {"title": "Step 4", "description": "Add all vegetables from firmest to softest."}, {"title": "Step 5", "description": "Add oyster sauce, soy sauce, and broth."}, {"title": "Step 6", "description": "Stir-fry on high heat 3-4 minutes."}, {"title": "Step 7", "description": "Add quail eggs if using."}, {"title": "Step 8", "description": "Pour cornstarch mixture to thicken sauce."}, {"title": "Step 9", "description": "Serve immediately."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Pork Igado', 'Braised', '', 'Medium', '', '1 person', 'approximately 1100 kcal per serving', 4294964192, '[{"name": "pork shoulder", "description": "150g"}, {"name": "pork liver", "description": "75g"}, {"name": "1/4 red bell pepper", "description": ""}, {"name": "green peas", "description": "2 tbsp"}, {"name": "1 1/2 tbsp vinegar", "description": ""}, {"name": "soy sauce", "description": "1 tbsp"}, {"name": "garlic", "description": "1 clove"}, {"name": "1/4 medium onion", "description": ""}, {"name": "peppercorns", "description": "1/4 tsp"}, {"name": "bay leaf", "description": "1 pc"}, {"name": "cooking oil", "description": "1 tsp"}]'::jsonb, '[{"title": "Step 1", "description": "Sauté garlic and onion in oil."}, {"title": "Step 2", "description": "Add pork; cook until browned."}, {"title": "Step 3", "description": "Add pork liver; cook 2 minutes."}, {"title": "Step 4", "description": "Pour vinegar; do not stir for 2 minutes."}, {"title": "Step 5", "description": "Add soy sauce, peppercorns, and bay leaves."}, {"title": "Step 6", "description": "Simmer 15-20 minutes until pork is tender and sauce reduces."}, {"title": "Step 7", "description": "Add bell pepper and green peas."}, {"title": "Step 8", "description": "Cook 3 more minutes. Serve."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Inihaw na Liempo', 'Grilled/Fried', '', 'Easy', '', '1 person', 'approximately 1350 kcal per serving', 4294964192, '[{"name": "pork belly", "description": "180g"}, {"name": "soy sauce", "description": "1 tbsp"}, {"name": "banana ketchup", "description": "1 tbsp"}, {"name": "calamansi juice", "description": "1 tbsp"}, {"name": "garlic", "description": "1 clove"}, {"name": "sugar", "description": "1 tsp"}, {"name": "black pepper", "description": "1/4 tsp"}, {"name": "7-Up or Sprite", "description": "1 tbsp"}]'::jsonb, '[{"title": "Step 1", "description": "Score pork belly skin every 2 inches."}, {"title": "Step 2", "description": "Combine all marinade ingredients. Marinate pork at least 4 hours or overnight."}, {"title": "Step 3", "description": "Prepare charcoal grill. Grill pork belly over medium heat."}, {"title": "Step 4", "description": "Baste with marinade every 3-4 minutes."}, {"title": "Step 5", "description": "Grill 20-25 minutes, flipping halfway, until cooked through with char marks."}, {"title": "Step 6", "description": "Rest 5 minutes before slicing."}, {"title": "Step 7", "description": "Serve with spiced vinegar and atchara (pickled papaya)."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Inihaw na Bangus', 'Grilled/Fried', '', 'Easy', '', '1 person', 'approximately 650 kcal per serving', 4294964192, '[{"name": "1/4 whole large bangus, cleaned", "description": ""}, {"name": "1/2 medium tomato", "description": ""}, {"name": "1/4 medium onion", "description": ""}, {"name": "1-inch ginger", "description": ""}, {"name": "soy sauce", "description": "1 tbsp"}, {"name": "calamansi juice", "description": "1 tbsp"}, {"name": "Salt and pepper", "description": ""}, {"name": "1 small banana leaf", "description": ""}]'::jsonb, '[{"title": "Step 1", "description": "Score bangus inside flesh."}, {"title": "Step 2", "description": "Marinate with soy sauce, calamansi, salt, and pepper for 20 minutes."}, {"title": "Step 3", "description": "Mix tomatoes, onion, and ginger. Stuff inside fish cavity."}, {"title": "Step 4", "description": "Wilt banana leaf over flame. Wrap fish tightly."}, {"title": "Step 5", "description": "Grill over medium charcoal heat, 15-20 minutes per side."}, {"title": "Step 6", "description": "Unwrap carefully; serve with rice and soy-vinegar dip."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Nilaga', 'Soup/Stew', '', 'Easy', '', '1 person', 'approximately 650 kcal per serving', 4294964192, '[{"name": "beef shank or pork ribs", "description": "150g"}, {"name": "1 medium potato", "description": ""}, {"name": "1/8 head cabbage", "description": ""}, {"name": "1/4 bundle pechay", "description": ""}, {"name": "1/4 medium onion", "description": ""}, {"name": "peppercorns", "description": "1/4 tsp"}, {"name": "fish sauce", "description": "1 tbsp"}, {"name": "liter water", "description": "1 l"}]'::jsonb, '[{"title": "Step 1", "description": "Blanch meat in boiling water 5 minutes. Rinse."}, {"title": "Step 2", "description": "Return meat to pot with fresh water, onion, and peppercorns."}, {"title": "Step 3", "description": "Boil; then simmer 1-1.5 hours until very tender."}, {"title": "Step 4", "description": "Add potatoes; cook 15 minutes."}, {"title": "Step 5", "description": "Add cabbage; cook 5 minutes."}, {"title": "Step 6", "description": "Add pechay; cook 2 minutes."}, {"title": "Step 7", "description": "Season generously with fish sauce. Serve hot."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Binagoongang Baboy', 'Sautéed', '', 'Easy', '', '1 person', 'approximately 1350 kcal per serving', 4294964192, '[{"name": "pork belly", "description": "150g"}, {"name": "bagoong alamang", "description": "1 tbsp"}, {"name": "1/2 medium tomato", "description": ""}, {"name": "garlic", "description": "1 clove"}, {"name": "1/4 medium onion", "description": ""}, {"name": "siling labuyo", "description": "1/2 pc"}, {"name": "vinegar", "description": "1 tsp"}, {"name": "sugar", "description": "1/2 tsp"}, {"name": "cooking oil", "description": "1 tsp"}]'::jsonb, '[{"title": "Step 1", "description": "Boil pork belly until tender. Slice into cubes."}, {"title": "Step 2", "description": "Pan-fry pork cubes until crispy. Drain and set aside."}, {"title": "Step 3", "description": "In same pan, sauté garlic, onion, and tomatoes."}, {"title": "Step 4", "description": "Add bagoong; cook 3 minutes stirring."}, {"title": "Step 5", "description": "Add chili, vinegar, and sugar. Balance flavors."}, {"title": "Step 6", "description": "Add crispy pork; toss to coat."}, {"title": "Step 7", "description": "Serve immediately over rice."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Pork Humba', 'Braised', '', 'Medium', '', '1 person', 'approximately 2250 kcal per serving', 4294964192, '[{"name": "pork belly", "description": "180g"}, {"name": "tausi", "description": "1 tsp"}, {"name": "palm or brown sugar", "description": "1 tsp"}, {"name": "vinegar", "description": "1 tbsp"}, {"name": "soy sauce", "description": "1 tbsp"}, {"name": "garlic", "description": "2 cloves"}, {"name": "bay leaf", "description": "1 pc"}, {"name": "dried banana blossom", "description": "2 tbsp"}, {"name": "water", "description": "1/4 cup"}]'::jsonb, '[{"title": "Step 1", "description": "Soak dried banana blossom in warm water 15 minutes. Drain."}, {"title": "Step 2", "description": "In a pot, combine all ingredients."}, {"title": "Step 3", "description": "Bring to a boil. Simmer covered on low heat 1-1.5 hours until pork is very tender."}, {"title": "Step 4", "description": "Uncover; increase heat slightly to reduce sauce until thick and dark."}, {"title": "Step 5", "description": "Stir to prevent burning as sauce thickens."}, {"title": "Step 6", "description": "Taste; adjust sugar and vinegar."}, {"title": "Step 7", "description": "Serve with steamed rice."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Ginisang Monggo', 'Soup/Stew', '', 'Easy', '', '1 person', 'approximately 430 kcal per serving', 4294964192, '[{"name": "mung beans, soaked", "description": "1/4 cup"}, {"name": "pork", "description": "100g"}, {"name": "tinapa flakes", "description": "2 tbsp"}, {"name": "ampalaya leaves or kangkong", "description": "1/2 cup"}, {"name": "garlic", "description": "1 clove"}, {"name": "1/4 medium onion", "description": ""}, {"name": "1/2 medium tomato", "description": ""}, {"name": "1 1/2 cups water", "description": ""}, {"name": "fish sauce", "description": "1 tbsp"}, {"name": "cooking oil", "description": "1 tsp"}]'::jsonb, '[{"title": "Step 1", "description": "Boil soaked monggo in water until tender and starting to break apart, about 30-40 minutes."}, {"title": "Step 2", "description": "In another pan, sauté garlic, onion, and tomatoes."}, {"title": "Step 3", "description": "Add pork; cook until done."}, {"title": "Step 4", "description": "Add tinapa flakes; stir."}, {"title": "Step 5", "description": "Combine with monggo; simmer together 10 minutes."}, {"title": "Step 6", "description": "Add greens; cook 2 minutes."}, {"title": "Step 7", "description": "Season with fish sauce. Serve."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Lumpiang Shanghai', 'Grilled/Fried', '', 'Medium', '', '1 person', 'approximately 1550 kcal per serving', 4294964192, '[{"name": "ground pork", "description": "150g"}, {"name": "1/4 medium carrot", "description": ""}, {"name": "singkamas", "description": "2 tbsp"}, {"name": "garlic", "description": "1 clove"}, {"name": "1/4 medium onion", "description": ""}, {"name": "arge egg, beaten", "description": "1/4 l"}, {"name": "soy sauce", "description": "1 tsp"}, {"name": "Salt and pepper", "description": ""}, {"name": "umpia wrappers", "description": "6-8 l"}, {"name": "Oil for frying", "description": ""}, {"name": "sweet chili sauce", "description": "2 tbsp"}]'::jsonb, '[{"title": "Step 1", "description": "Mix ground pork, carrot, singkamas, garlic, onion, egg, and soy sauce. Season."}, {"title": "Step 2", "description": "Lay one lumpia wrapper diagonally. Spoon 2 tbsp filling across the bottom third."}, {"title": "Step 3", "description": "Fold bottom over filling, then fold in sides. Roll tightly. Seal edge with egg or water."}, {"title": "Step 4", "description": "Repeat until filling is used."}, {"title": "Step 5", "description": "Heat oil to 170°C. Fry lumpia in batches until golden, about 5-7 minutes."}, {"title": "Step 6", "description": "Drain on rack. Serve hot with sweet chili sauce."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Chicken Inasal', 'Grilled/Fried', '', 'Medium', '', '1 person', 'approximately 650 kcal per serving', 4294964192, '[{"name": "chicken", "description": "150g"}, {"name": "calamansi juice", "description": "1 tbsp"}, {"name": "coconut vinegar", "description": "1 tbsp"}, {"name": "lemongrass", "description": "1 stalk"}, {"name": "garlic", "description": "1 clove"}, {"name": "1-inch ginger", "description": ""}, {"name": "annatto oil", "description": "1 tbsp"}, {"name": "salt", "description": "1/4 tsp"}, {"name": "sugar", "description": "1/4 tsp"}]'::jsonb, '[{"title": "Step 1", "description": "Make annatto oil: heat seeds in oil until color releases. Strain; cool."}, {"title": "Step 2", "description": "Combine calamansi, vinegar, lemongrass, garlic, ginger, salt, and sugar."}, {"title": "Step 3", "description": "Marinate chicken at least 4 hours, ideally overnight."}, {"title": "Step 4", "description": "Thread on skewers for easier grilling."}, {"title": "Step 5", "description": "Grill over medium charcoal heat, basting with annatto oil every few minutes."}, {"title": "Step 6", "description": "Cook 20-25 minutes until juices run clear."}, {"title": "Step 7", "description": "Serve with garlic rice, spiced sinamak vinegar, and atchara."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Tinolang Tahong', 'Soup/Stew', '', 'Easy', '', '1 person', 'approximately 280 kcal per serving', 4294964192, '[{"name": "fresh tahong", "description": "200g"}, {"name": "1-inch ginger", "description": ""}, {"name": "garlic", "description": "1 clove"}, {"name": "1/4 medium onion", "description": ""}, {"name": "malunggay leaves", "description": "1/2 cup"}, {"name": "water", "description": "1/4 cup"}, {"name": "fish sauce", "description": "1 tbsp"}, {"name": "cooking oil", "description": "1 tsp"}]'::jsonb, '[{"title": "Step 1", "description": "Sauté garlic and ginger in oil over medium heat until fragrant."}, {"title": "Step 2", "description": "Add onion; cook 2 minutes."}, {"title": "Step 3", "description": "Add mussels; stir to coat."}, {"title": "Step 4", "description": "Pour water over mussels. Cover with lid."}, {"title": "Step 5", "description": "Steam 5-7 minutes until mussels open."}, {"title": "Step 6", "description": "Discard any that don''t open."}, {"title": "Step 7", "description": "Add malunggay leaves. Season with fish sauce."}, {"title": "Step 8", "description": "Cook 1 more minute. Serve immediately."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Ginataang Hipon', 'Sautéed', '', 'Easy', '', '1 person', 'approximately 1200 kcal per serving', 4294964192, '[{"name": "large shrimp", "description": "150g"}, {"name": "coconut milk", "description": "150ml"}, {"name": "bagoong alamang", "description": "1 tsp"}, {"name": "garlic", "description": "1 clove"}, {"name": "1/4 medium onion", "description": ""}, {"name": "siling haba", "description": "1 pc"}, {"name": "siling labuyo", "description": "1/2 pc"}, {"name": "cooking oil", "description": "1 tsp"}, {"name": "Salt and pepper", "description": ""}]'::jsonb, '[{"title": "Step 1", "description": "Heat oil; sauté garlic and onion."}, {"title": "Step 2", "description": "Add bagoong; stir 1 minute."}, {"title": "Step 3", "description": "Add shrimp; cook 2 minutes until pink."}, {"title": "Step 4", "description": "Add all chilis."}, {"title": "Step 5", "description": "Pour coconut milk. Bring to a simmer."}, {"title": "Step 6", "description": "Cook 8-10 minutes until sauce thickens slightly."}, {"title": "Step 7", "description": "Season with salt and pepper."}, {"title": "Step 8", "description": "Serve hot over rice."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Kilawin na Tanigue', 'Salad/Fresh', '', 'Easy', '', '1 person', 'approximately 650 kcal per serving', 4294964192, '[{"name": "fresh tanigue", "description": "150g"}, {"name": "calamansi juice", "description": "2 tbsp"}, {"name": "coconut vinegar", "description": "1 tbsp"}, {"name": "1-inch ginger", "description": ""}, {"name": "red onion", "description": "2 tbsp"}, {"name": "siling labuyo", "description": "1/2 pc"}, {"name": "coconut cream", "description": "1 tbsp"}, {"name": "Salt and pepper", "description": ""}]'::jsonb, '[{"title": "Step 1", "description": "Use only the freshest sashimi-grade fish."}, {"title": "Step 2", "description": "Cube fish into 1-inch pieces."}, {"title": "Step 3", "description": "Combine calamansi and vinegar. Pour over fish."}, {"title": "Step 4", "description": "Toss; marinate 20-30 minutes until fish turns opaque (acid-cooked)."}, {"title": "Step 5", "description": "Drain some liquid."}, {"title": "Step 6", "description": "Add ginger, onion, and chili. Toss."}, {"title": "Step 7", "description": "Add coconut cream. Toss gently."}, {"title": "Step 8", "description": "Season with salt and pepper. Serve cold."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Adobong Pusit', 'Braised', '', 'Medium', '', '1 person', 'approximately 650 kcal per serving', 4294964192, '[{"name": "pusit", "description": "200g"}, {"name": "vinegar", "description": "1 tbsp"}, {"name": "soy sauce", "description": "1 tbsp"}, {"name": "garlic", "description": "1 clove"}, {"name": "1/4 medium onion", "description": ""}, {"name": "1/2 medium tomato", "description": ""}, {"name": "cooking oil", "description": "1 tsp"}, {"name": "Salt and pepper", "description": ""}]'::jsonb, '[{"title": "Step 1", "description": "Clean squid carefully, reserving ink sacs intact."}, {"title": "Step 2", "description": "Heat oil; sauté garlic, onion, and tomatoes."}, {"title": "Step 3", "description": "Add squid bodies and tentacles; cook 2 minutes."}, {"title": "Step 4", "description": "Add vinegar; let cook without stirring 2 minutes."}, {"title": "Step 5", "description": "Add soy sauce and ink sacs (pierce carefully over the pan)."}, {"title": "Step 6", "description": "Stir; simmer 10-12 minutes until sauce is thick and ink-black."}, {"title": "Step 7", "description": "Season; serve with rice."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Pakbet Ilocano', 'Sautéed', '', 'Easy', '', '1 person', 'approximately 700 kcal per serving', 4294964192, '[{"name": "1/4 medium ampalaya", "description": ""}, {"name": "1/4 medium eggplant", "description": ""}, {"name": "kalabasa", "description": "1/4 cup"}, {"name": "okra", "description": "50g"}, {"name": "sitaw", "description": "50g"}, {"name": "1/2 medium tomato", "description": ""}, {"name": "pork", "description": "100g"}, {"name": "bagoong isda", "description": "1 tbsp"}, {"name": "water", "description": "2 tbsp"}, {"name": "cooking oil", "description": "1 tsp"}]'::jsonb, '[{"title": "Step 1", "description": "In a pot, arrange pork at the bottom."}, {"title": "Step 2", "description": "Layer vegetables by cooking time: kalabasa, eggplant, sitaw, ampalaya, okra, tomatoes on top."}, {"title": "Step 3", "description": "Dissolve bagoong isda in water; pour over vegetables."}, {"title": "Step 4", "description": "Bring to a boil; do not stir."}, {"title": "Step 5", "description": "Lower heat; cover and simmer 15-20 minutes."}, {"title": "Step 6", "description": "Once vegetables are tender, gently fold once."}, {"title": "Step 7", "description": "Taste; adjust with more bagoong."}, {"title": "Step 8", "description": "Serve."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Pork Sisig', 'Grilled/Fried', '', 'Medium', '', '1 person', 'approximately 1350 kcal per serving', 4294964192, '[{"name": "pork cheeks and ears", "description": "180g"}, {"name": "chicken liver", "description": "50g"}, {"name": "arge onion", "description": "1/4 l"}, {"name": "siling labuyo", "description": "1 pc"}, {"name": "calamansi juice", "description": "1 tbsp"}, {"name": "soy sauce", "description": "1 tsp"}, {"name": "mayonnaise", "description": "1 tsp"}, {"name": "Salt and pepper", "description": ""}, {"name": "arge egg, optional", "description": "1/2 l"}]'::jsonb, '[{"title": "Step 1", "description": "Boil pork cheeks and ears until tender (about 45 minutes). Drain."}, {"title": "Step 2", "description": "Grill boiled pork and chicken liver until charred. Chop into small pieces."}, {"title": "Step 3", "description": "Heat sizzling plate (cast iron) until very hot."}, {"title": "Step 4", "description": "Add butter; toss in pork and liver."}, {"title": "Step 5", "description": "Add onion and chili; sear together."}, {"title": "Step 6", "description": "Season with soy sauce and calamansi."}, {"title": "Step 7", "description": "Add mayonnaise; toss."}, {"title": "Step 8", "description": "Crack egg on top (optional); mix before eating."}, {"title": "Step 9", "description": "Serve sizzling."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Ginataang Manok', 'Braised', '', 'Easy', '', '1 person', 'approximately 1500 kcal per serving', 4294964192, '[{"name": "chicken", "description": "150g"}, {"name": "coconut milk", "description": "150ml"}, {"name": "coconut cream", "description": "75ml"}, {"name": "1-inch ginger", "description": ""}, {"name": "garlic", "description": "2 cloves"}, {"name": "1/4 medium onion", "description": ""}, {"name": "siling haba", "description": "1 pc"}, {"name": "fish sauce", "description": "1 tbsp"}, {"name": "cooking oil", "description": "1 tsp"}]'::jsonb, '[{"title": "Step 1", "description": "Sauté ginger in oil until fragrant."}, {"title": "Step 2", "description": "Add garlic and onion; cook until soft."}, {"title": "Step 3", "description": "Add chicken; brown on all sides."}, {"title": "Step 4", "description": "Pour coconut milk. Bring to a boil."}, {"title": "Step 5", "description": "Add chilis. Simmer covered 20-25 minutes."}, {"title": "Step 6", "description": "Add coconut cream. Simmer uncovered 10 minutes until sauce thickens."}, {"title": "Step 7", "description": "Season with fish sauce. Serve."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Pininyahang Manok', 'Braised', '', 'Easy', '', '1 person', 'approximately 1100 kcal per serving', 4294964192, '[{"name": "chicken", "description": "150g"}, {"name": "pineapple chunks with 2 tbsp juice", "description": "1/2 cup"}, {"name": "all-purpose cream", "description": "100ml"}, {"name": "1/2 medium potato", "description": ""}, {"name": "1/2 medium carrot", "description": ""}, {"name": "1/4 medium onion", "description": ""}, {"name": "garlic", "description": "1 clove"}, {"name": "soy sauce", "description": "1 tsp"}, {"name": "cooking oil", "description": "1 tsp"}, {"name": "Salt and pepper", "description": ""}]'::jsonb, '[{"title": "Step 1", "description": "Brown chicken in oil. Remove and set aside."}, {"title": "Step 2", "description": "Sauté garlic and onion."}, {"title": "Step 3", "description": "Return chicken. Add pineapple juice and soy sauce."}, {"title": "Step 4", "description": "Simmer 20 minutes."}, {"title": "Step 5", "description": "Add potatoes and carrots. Cook 12 minutes."}, {"title": "Step 6", "description": "Add pineapple chunks and cream."}, {"title": "Step 7", "description": "Simmer 5 more minutes."}, {"title": "Step 8", "description": "Season; serve."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Kinilaw na Tuna', 'Salad/Fresh', '', 'Easy', '', '1 person', 'approximately 750 kcal per serving', 4294964192, '[{"name": "sashimi-grade fresh tuna", "description": "150g"}, {"name": "1 1/2 tbsp coconut vinegar", "description": ""}, {"name": "calamansi juice", "description": "1 tbsp"}, {"name": "1-inch ginger", "description": ""}, {"name": "red onion", "description": "2 tbsp"}, {"name": "siling labuyo", "description": "1/2 pc"}, {"name": "coconut cream", "description": "1 tbsp"}, {"name": "Salt and pepper", "description": ""}]'::jsonb, '[{"title": "Step 1", "description": "Cube tuna into 1-inch pieces."}, {"title": "Step 2", "description": "Toss with vinegar and calamansi. Let sit 15-20 minutes until opaque."}, {"title": "Step 3", "description": "Drain most liquid."}, {"title": "Step 4", "description": "Add ginger, onion, and chili. Mix."}, {"title": "Step 5", "description": "Add coconut cream. Toss gently."}, {"title": "Step 6", "description": "Season with salt and pepper."}, {"title": "Step 7", "description": "Serve cold immediately."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Pancit Batchoy', 'Noodles/Rice', '', 'Hard', '', '1 person', 'approximately 2100 kcal per serving', 4294964192, '[{"name": "fresh miki noodles", "description": "100g"}, {"name": "pork", "description": "75g"}, {"name": "pork liver", "description": "40g"}, {"name": "pork intestine", "description": "40g"}, {"name": "chicharon", "description": "20g"}, {"name": "1 1/2 cups pork bone broth", "description": ""}, {"name": "garlic", "description": "1 clove"}, {"name": "shrimp paste", "description": "1 tsp"}, {"name": "Fish sauce", "description": ""}, {"name": "green onion", "description": "1 tbsp"}]'::jsonb, '[{"title": "Step 1", "description": "Make broth: boil pork bones 2 hours with garlic, onion, shrimp paste. Strain."}, {"title": "Step 2", "description": "Cook intestines separately; slice."}, {"title": "Step 3", "description": "Blanch noodles in boiling water. Divide into bowls."}, {"title": "Step 4", "description": "In broth, quickly cook pork slices and liver (30 seconds)."}, {"title": "Step 5", "description": "Ladle hot broth with meat over noodles."}, {"title": "Step 6", "description": "Top with intestine, chicharron, fried garlic, green onion."}, {"title": "Step 7", "description": "Serve with fish sauce and calamansi."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Karekare sa Gabi', 'Soup/Stew', '', 'Medium', '', '1 person', 'approximately 350 kcal per serving', 4294964192, '[{"name": "gabi", "description": "1/2 cup"}, {"name": "eggplant", "description": "1/4 cup"}, {"name": "sitaw", "description": "1/4 cup"}, {"name": "pechay", "description": "1/4 cup"}, {"name": "banana blossom", "description": "2 tbsp"}, {"name": "peanut butter", "description": "1 tbsp"}, {"name": "ground peanuts", "description": "1 tbsp"}, {"name": "annatto water", "description": "1 tsp"}, {"name": "1/4 medium onion", "description": ""}, {"name": "garlic", "description": "1 clove"}, {"name": "broth", "description": "3/4 cup"}, {"name": "bagoong", "description": "1 tbsp"}]'::jsonb, '[{"title": "Step 1", "description": "Sauté garlic and onion in oil."}, {"title": "Step 2", "description": "Add annatto water; cook 1 minute."}, {"title": "Step 3", "description": "Add peanut butter and ground peanuts; stir."}, {"title": "Step 4", "description": "Slowly add broth, stirring to prevent lumps."}, {"title": "Step 5", "description": "Add gabi; simmer until almost tender, 12 minutes."}, {"title": "Step 6", "description": "Add eggplant and banana blossom."}, {"title": "Step 7", "description": "Add sitaw and pechay last."}, {"title": "Step 8", "description": "Serve with bagoong on side."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Pinapaitan', 'Soup/Stew', '', 'Hard', '', '1 person', 'approximately 1150 kcal per serving', 4294964192, '[{"name": "goat tripe and meat", "description": "150g"}, {"name": "bile", "description": "1 tsp"}, {"name": "1-inch ginger", "description": ""}, {"name": "siling labuyo", "description": "1 pc"}, {"name": "1/4 medium onion", "description": ""}, {"name": "garlic", "description": "1 clove"}, {"name": "fish sauce", "description": "1 tbsp"}, {"name": "water", "description": "1 cup"}]'::jsonb, '[{"title": "Step 1", "description": "Boil goat meat and tripe with ginger, garlic, and onion until tender, about 1 hour."}, {"title": "Step 2", "description": "Remove meat; slice thinly."}, {"title": "Step 3", "description": "Return to broth."}, {"title": "Step 4", "description": "Add bile gradually — 1 tbsp at a time. Taste after each addition."}, {"title": "Step 5", "description": "Add chilis. Simmer 10 minutes."}, {"title": "Step 6", "description": "Season with fish sauce."}, {"title": "Step 7", "description": "Serve hot."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Sinanglay na Isda', 'Braised', '', 'Medium', '', '1 person', 'approximately 700 kcal per serving', 4294964192, '[{"name": "tilapia", "description": "200g"}, {"name": "1/2 medium tomato", "description": ""}, {"name": "1/4 medium onion", "description": ""}, {"name": "1-inch ginger", "description": ""}, {"name": "coconut milk", "description": "150ml"}, {"name": "siling haba", "description": "1 pc"}, {"name": "Pechay or leafy greens", "description": ""}, {"name": "fish sauce", "description": "1 tbsp"}, {"name": "Salt and pepper", "description": ""}]'::jsonb, '[{"title": "Step 1", "description": "Season fish inside and out with salt and pepper."}, {"title": "Step 2", "description": "Mix tomatoes, onion, and ginger; stuff into fish cavity."}, {"title": "Step 3", "description": "Wrap each fish in pechay leaves, securing with pandan or string."}, {"title": "Step 4", "description": "Arrange in pot. Pour coconut milk over."}, {"title": "Step 5", "description": "Add chilis."}, {"title": "Step 6", "description": "Simmer covered 20-25 minutes until fish is cooked and coconut milk reduced."}, {"title": "Step 7", "description": "Season with fish sauce. Serve."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Daing na Bangus', 'Grilled/Fried', '', 'Easy', '', '1 person', 'approximately 550 kcal per serving', 4294964192, '[{"name": "arge bangus, butterflied and deboned", "description": "1/4 l"}, {"name": "white vinegar", "description": "2 tbsp"}, {"name": "garlic", "description": "2 cloves"}, {"name": "peppercorns", "description": "1/4 tsp"}, {"name": "salt", "description": "1/4 tsp"}, {"name": "cooking oil", "description": "1 tbsp"}]'::jsonb, '[{"title": "Step 1", "description": "Combine vinegar, garlic, peppercorns, and salt."}, {"title": "Step 2", "description": "Place bangus flesh-side down in marinade. Refrigerate overnight (minimum 8 hours)."}, {"title": "Step 3", "description": "Drain and pat dry."}, {"title": "Step 4", "description": "Heat generous oil in pan over medium-high heat."}, {"title": "Step 5", "description": "Fry flesh-side up first for 4-5 minutes, then skin-side until crispy."}, {"title": "Step 6", "description": "Drain. Serve with garlic rice and sunny-side-up eggs."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Longganisang Hubad', 'Grilled/Fried', '', 'Easy', '', '1 person', 'approximately 1320 kcal per serving', 4294964192, '[{"name": "ground pork", "description": "150g"}, {"name": "garlic", "description": "2 cloves"}, {"name": "sugar", "description": "1 tsp"}, {"name": "vinegar", "description": "1 tsp"}, {"name": "salt", "description": "1/4 tsp"}, {"name": "black pepper", "description": "1/8 tsp"}, {"name": "soy sauce", "description": "1 tsp"}]'::jsonb, '[{"title": "Step 1", "description": "Combine all ingredients thoroughly. Refrigerate overnight."}, {"title": "Step 2", "description": "Shape into small oval logs."}, {"title": "Step 3", "description": "Cook in pan with a little oil over medium heat."}, {"title": "Step 4", "description": "As fat renders, increase heat slightly."}, {"title": "Step 5", "description": "Cook until caramelized and cooked through, about 8-10 minutes."}, {"title": "Step 6", "description": "Serve with garlic rice, egg, and vinegar dip."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Bagoong Guisado', 'Preserved', '', 'Easy', '', '1 person', 'approximately 420 kcal per serving', 4294964192, '[{"name": "bagoong alamang", "description": "2 tbsp"}, {"name": "pork", "description": "75g"}, {"name": "garlic", "description": "1 clove"}, {"name": "1/4 medium onion", "description": ""}, {"name": "1/2 medium tomato", "description": ""}, {"name": "vinegar", "description": "1 tsp"}, {"name": "sugar", "description": "1/2 tsp"}, {"name": "siling labuyo, optional", "description": "1/2 pc"}, {"name": "cooking oil", "description": "1 tsp"}]'::jsonb, '[{"title": "Step 1", "description": "Heat oil; sauté garlic, onion, and tomatoes until soft."}, {"title": "Step 2", "description": "Add pork; cook until browned."}, {"title": "Step 3", "description": "Add bagoong; stir and cook 5 minutes."}, {"title": "Step 4", "description": "Add vinegar; cook 2 minutes."}, {"title": "Step 5", "description": "Add sugar; balance flavors."}, {"title": "Step 6", "description": "Simmer on low 10 minutes until well-combined."}, {"title": "Step 7", "description": "Cool and store in jar. Keeps 2 weeks refrigerated."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Ginataang Tambo', 'Sautéed', '', 'Easy', '', '1 person', 'approximately 1900 kcal per serving', 4294964192, '[{"name": "labong", "description": "150g"}, {"name": "coconut milk", "description": "150ml"}, {"name": "pork belly", "description": "75g"}, {"name": "shrimp", "description": "75g"}, {"name": "garlic", "description": "1 clove"}, {"name": "1/4 medium onion", "description": ""}, {"name": "siling haba", "description": "1 pc"}, {"name": "bagoong alamang", "description": "1 tsp"}, {"name": "cooking oil", "description": "1 tsp"}]'::jsonb, '[{"title": "Step 1", "description": "Boil labong in several changes of water (3x) for 20 minutes total to remove bitterness and toxins."}, {"title": "Step 2", "description": "Drain; squeeze dry."}, {"title": "Step 3", "description": "Sauté garlic and onion. Add pork; brown."}, {"title": "Step 4", "description": "Add shrimp; cook 1 minute."}, {"title": "Step 5", "description": "Add labong; stir."}, {"title": "Step 6", "description": "Add bagoong and chilis."}, {"title": "Step 7", "description": "Pour coconut milk; simmer 15 minutes until thick."}, {"title": "Step 8", "description": "Season; serve."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Pochero', 'Soup/Stew', '', 'Hard', '', '1 person', 'approximately 1550 kcal per serving', 4294964192, '[{"name": "beef shank", "description": "100g"}, {"name": "pork belly", "description": "75g"}, {"name": "chorizo de Bilbao", "description": "1/2 pc"}, {"name": "saba", "description": "1/2 pc"}, {"name": "1/2 medium potato", "description": ""}, {"name": "1/8 head cabbage", "description": ""}, {"name": "1/4 bundle pechay", "description": ""}, {"name": "chickpeas", "description": "1/4 cup"}, {"name": "1/4 medium onion", "description": ""}, {"name": "tomato sauce", "description": "1/2 cup"}]'::jsonb, '[{"title": "Step 1", "description": "Boil beef and pork together 1 hour until tender."}, {"title": "Step 2", "description": "Add chorizo; cook 15 minutes."}, {"title": "Step 3", "description": "Add saba and chickpeas."}, {"title": "Step 4", "description": "Add potatoes; cook 15 minutes."}, {"title": "Step 5", "description": "Add cabbage and pechay."}, {"title": "Step 6", "description": "Serve each component in a bowl."}, {"title": "Step 7", "description": "Serve sautéed tomato sauce separately for dipping."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Morcon', 'Braised', '', 'Hard', '', '1 person', 'approximately 2150 kcal per serving', 4294964192, '[{"name": "beef flank", "description": "180g"}, {"name": "1/2 hard-boiled egg", "description": ""}, {"name": "1/4 medium carrot", "description": ""}, {"name": "sweet pickles", "description": "1 tbsp"}, {"name": "hotdog", "description": "1/2 pc"}, {"name": "tomato sauce", "description": "1/2 cup"}, {"name": "soy sauce", "description": "1 tbsp"}, {"name": "water", "description": "1/4 cup"}, {"name": "Salt and pepper", "description": ""}, {"name": "toothpicks or kitchen string", "description": ""}]'::jsonb, '[{"title": "Step 1", "description": "Pound beef flat. Season with soy sauce, salt, and pepper."}, {"title": "Step 2", "description": "Arrange stuffing (eggs, carrots, pickles, hotdog) along one edge."}, {"title": "Step 3", "description": "Roll tightly; tie with string or secure with toothpicks."}, {"title": "Step 4", "description": "Brown roll on all sides in hot oil."}, {"title": "Step 5", "description": "Place in pot with tomato sauce, soy sauce, and water."}, {"title": "Step 6", "description": "Simmer covered 1.5-2 hours until tender."}, {"title": "Step 7", "description": "Remove string; slice into rounds."}, {"title": "Step 8", "description": "Reduce sauce; pour over slices."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Embutido', 'Braised', '', 'Medium', '', '1 person', 'approximately 1900 kcal per serving', 4294964192, '[{"name": "ground pork", "description": "150g"}, {"name": "1 hard-boiled egg", "description": ""}, {"name": "raisins", "description": "1 tbsp"}, {"name": "1/4 red bell pepper", "description": ""}, {"name": "sweet pickle relish", "description": "1 tsp"}, {"name": "breadcrumbs", "description": "1 tbsp"}, {"name": "arge egg, raw", "description": "1/4 l"}, {"name": "soy sauce", "description": "1 tsp"}, {"name": "Salt and pepper", "description": ""}, {"name": "Aluminum foil", "description": ""}]'::jsonb, '[{"title": "Step 1", "description": "Combine ground pork, raw egg, breadcrumbs, bell pepper, relish, raisins, soy sauce. Season."}, {"title": "Step 2", "description": "Lay mixture on foil; flatten into a rectangle."}, {"title": "Step 3", "description": "Place whole boiled eggs along one edge."}, {"title": "Step 4", "description": "Roll into a log, encasing the eggs in the center."}, {"title": "Step 5", "description": "Seal foil tightly."}, {"title": "Step 6", "description": "Steam for 45-50 minutes."}, {"title": "Step 7", "description": "Cool before unwrapping. Slice to reveal egg center."}, {"title": "Step 8", "description": "Pan-fry slices optionally for a browned exterior."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Ginataang Kuhol', 'Braised', '', 'Medium', '', '1 person', 'approximately 1400 kcal per serving', 4294964192, '[{"name": "kuhol", "description": "200g"}, {"name": "coconut milk", "description": "150ml"}, {"name": "bagoong alamang", "description": "1 tsp"}, {"name": "1-inch ginger", "description": ""}, {"name": "garlic", "description": "1 clove"}, {"name": "1/4 medium onion", "description": ""}, {"name": "siling haba", "description": "1 pc"}, {"name": "siling labuyo", "description": "1/2 pc"}, {"name": "cooking oil", "description": "1 tsp"}]'::jsonb, '[{"title": "Step 1", "description": "Clean snails: soak in salted water 30 minutes, scrub shells, trim off sealed operculum."}, {"title": "Step 2", "description": "Sauté ginger, garlic, and onion in oil."}, {"title": "Step 3", "description": "Add bagoong; cook 2 minutes."}, {"title": "Step 4", "description": "Add snails; stir to coat."}, {"title": "Step 5", "description": "Pour coconut milk. Add chilis."}, {"title": "Step 6", "description": "Simmer covered 20-25 minutes until snails are tender."}, {"title": "Step 7", "description": "Uncover; reduce sauce 5 minutes."}, {"title": "Step 8", "description": "Serve — suck meat from shells at the table."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Adobong Kangkong', 'Sautéed', '', 'Easy', '', '1 person', 'approximately 250 kcal per serving', 4294964192, '[{"name": "1/2 bundle kangkong", "description": ""}, {"name": "garlic", "description": "1 clove"}, {"name": "vinegar", "description": "1 tbsp"}, {"name": "soy sauce", "description": "1 tbsp"}, {"name": "pork or shrimp", "description": "100g"}, {"name": "cooking oil", "description": "1 tsp"}, {"name": "Salt and pepper", "description": ""}]'::jsonb, '[{"title": "Step 1", "description": "Separate kangkong leaves from stems. Cut stems into 2-inch pieces."}, {"title": "Step 2", "description": "Heat oil; sauté garlic until golden."}, {"title": "Step 3", "description": "Add pork; cook until browned."}, {"title": "Step 4", "description": "Add kangkong stems; stir-fry 1 minute."}, {"title": "Step 5", "description": "Add kangkong leaves."}, {"title": "Step 6", "description": "Add vinegar and soy sauce. Cover; cook 2 minutes."}, {"title": "Step 7", "description": "Season and serve immediately."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Ukoy', 'Grilled/Fried', '', 'Medium', '', '1 person', 'approximately 360 kcal per serving', 4294964192, '[{"name": "small shrimp", "description": "100g"}, {"name": "kalabasa", "description": "1/4 cup"}, {"name": "bean sprouts", "description": "1/4 cup"}, {"name": "flour", "description": "2 tbsp"}, {"name": "cornstarch", "description": "1 tbsp"}, {"name": "arge egg", "description": "1/2 l"}, {"name": "water", "description": "2 tbsp"}, {"name": "Salt and pepper", "description": ""}, {"name": "Oil for deep-frying", "description": ""}, {"name": "spiced vinegar", "description": "2 tbsp"}]'::jsonb, '[{"title": "Step 1", "description": "Make batter: whisk flour, cornstarch, egg, water, salt, and pepper."}, {"title": "Step 2", "description": "Add shrimp, kalabasa, and bean sprouts. Mix."}, {"title": "Step 3", "description": "Batter should be thin enough to drop spoonfuls."}, {"title": "Step 4", "description": "Heat oil to 175°C."}, {"title": "Step 5", "description": "Drop tablespoon-sized portions into oil."}, {"title": "Step 6", "description": "Fry 3-4 minutes per side until golden and very crispy."}, {"title": "Step 7", "description": "Drain. Serve with spiced vinegar."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Crispy Pata', 'Grilled/Fried', '', 'Hard', '', '1 person', 'approximately 1450 kcal per serving', 4294964192, '[{"name": "pork leg, cut into a serving portion", "description": "300g"}, {"name": "salt", "description": "1/2 tsp"}, {"name": "pepper", "description": "1/4 tsp"}, {"name": "garlic powder", "description": "1/4 tsp"}, {"name": "bay leaf", "description": "1 pc"}, {"name": "peppercorns", "description": "1/4 tsp"}, {"name": "Oil for deep-frying", "description": ""}, {"name": "soy sauce and 1 tbsp vinegar with onion and chili for dipping", "description": "1 tbsp"}]'::jsonb, '[{"title": "Step 1", "description": "Boil pata with bay leaves, peppercorns, and salt for 1.5-2 hours until very tender."}, {"title": "Step 2", "description": "Remove; pat completely dry."}, {"title": "Step 3", "description": "Rub with salt, pepper, and garlic powder."}, {"title": "Step 4", "description": "Air-dry uncovered in refrigerator for at least 8 hours."}, {"title": "Step 5", "description": "Heat deep frying oil to 180°C in a large pot."}, {"title": "Step 6", "description": "Carefully lower pata into oil. Fry 25-30 minutes, basting with oil."}, {"title": "Step 7", "description": "Remove when skin is deeply golden and shatteringly crispy."}, {"title": "Step 8", "description": "Drain; rest 5 minutes. Serve whole with dipping sauce."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Liempo sa Gata', 'Braised', '', 'Medium', '', '1 person', 'approximately 1650 kcal per serving', 4294964192, '[{"name": "pork belly", "description": "180g"}, {"name": "coconut milk", "description": "150ml"}, {"name": "coconut cream", "description": "75ml"}, {"name": "siling labuyo", "description": "1 pc"}, {"name": "siling haba", "description": "1 pc"}, {"name": "garlic", "description": "1 clove"}, {"name": "1/4 medium onion", "description": ""}, {"name": "bagoong alamang", "description": "1 tsp"}, {"name": "cooking oil", "description": "1 tsp"}]'::jsonb, '[{"title": "Step 1", "description": "Brown pork belly in oil. Remove; set aside."}, {"title": "Step 2", "description": "Sauté garlic and onion in same pan."}, {"title": "Step 3", "description": "Return pork. Add bagoong; stir."}, {"title": "Step 4", "description": "Pour coconut milk. Add all chilis."}, {"title": "Step 5", "description": "Simmer covered 25 minutes until pork is tender."}, {"title": "Step 6", "description": "Add coconut cream. Simmer uncovered until oil separates."}, {"title": "Step 7", "description": "Serve with steamed rice."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Hardinera', 'Braised', '', 'Hard', '', '1 person', 'approximately 1250 kcal per serving', 4294964192, '[{"name": "ground pork", "description": "150g"}, {"name": "raisins", "description": "1 tbsp"}, {"name": "1/4 red bell pepper", "description": ""}, {"name": "green peas", "description": "2 tbsp"}, {"name": "1 hard-boiled egg", "description": ""}, {"name": "pineapple tidbits", "description": "1/2 cup"}, {"name": "soy sauce", "description": "1 tsp"}, {"name": "Salt and pepper", "description": ""}, {"name": "gelatin dissolved in 1/4 cup hot broth", "description": "1 tsp"}]'::jsonb, '[{"title": "Step 1", "description": "Cook ground pork with all vegetables, raisins, soy sauce, and seasoning."}, {"title": "Step 2", "description": "Add pineapple tidbits; cook 2 minutes."}, {"title": "Step 3", "description": "Dissolve gelatin in hot broth; add to pork mixture."}, {"title": "Step 4", "description": "Layer hard-boiled eggs at bottom of greased mold."}, {"title": "Step 5", "description": "Pour pork mixture over eggs."}, {"title": "Step 6", "description": "Steam for 45 minutes."}, {"title": "Step 7", "description": "Cool; refrigerate 3+ hours until set."}, {"title": "Step 8", "description": "Unmold. Slice to reveal eggs. Serve cold."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Pork BBQ', 'Grilled/Fried', '', 'Easy', '', '1 person', 'approximately 1350 kcal per serving', 4294964192, '[{"name": "pork shoulder", "description": "180g"}, {"name": "soy sauce", "description": "1 tbsp"}, {"name": "banana ketchup", "description": "1 tbsp"}, {"name": "calamansi juice", "description": "1 tbsp"}, {"name": "garlic", "description": "1 clove"}, {"name": "sugar", "description": "1 tsp"}, {"name": "7-Up or Sprite", "description": "2 tbsp"}, {"name": "black pepper", "description": "1/4 tsp"}, {"name": "4-6 bamboo skewers", "description": ""}]'::jsonb, '[{"title": "Step 1", "description": "Combine all marinade ingredients. Marinate pork at least 4 hours; overnight is best."}, {"title": "Step 2", "description": "Thread pork strips onto skewers in an ''S'' pattern."}, {"title": "Step 3", "description": "Grill over charcoal on medium heat."}, {"title": "Step 4", "description": "Baste with reserved marinade every 3-4 minutes."}, {"title": "Step 5", "description": "Cook 20-25 minutes, flipping regularly, until cooked with sweet char marks."}, {"title": "Step 6", "description": "Serve with spiced vinegar and steamed rice."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Chicharon Bulaklak', 'Grilled/Fried', '', 'Hard', '', '1 person', 'approximately 3200 kcal per serving', 4294964192, '[{"name": "pork mesentery", "description": "150g"}, {"name": "salt", "description": "1/2 tsp"}, {"name": "peppercorns", "description": "1/4 tsp"}, {"name": "garlic", "description": "1 clove"}, {"name": "bay leaf", "description": "1 pc"}, {"name": "Oil for deep-frying", "description": ""}, {"name": "spiced vinegar", "description": "2 tbsp"}]'::jsonb, '[{"title": "Step 1", "description": "Clean mesentery very thoroughly with salt and vinegar. Rinse."}, {"title": "Step 2", "description": "Boil with garlic, peppercorns, bay leaves, and salt for 1 hour until tender."}, {"title": "Step 3", "description": "Drain; cut into pieces."}, {"title": "Step 4", "description": "Air-dry completely — at least 4 hours or overnight."}, {"title": "Step 5", "description": "Deep-fry at 180°C until puffed, golden, and very crispy."}, {"title": "Step 6", "description": "Drain on rack."}, {"title": "Step 7", "description": "Serve immediately with spiced vinegar."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Pinoy Chopsuey', 'Sautéed', '', 'Easy', '', '1 person', 'approximately 600 kcal per serving', 4294964192, '[{"name": "squid balls", "description": "3 pcs"}, {"name": "quail eggs", "description": "2 pcs"}, {"name": "snap peas", "description": "50g"}, {"name": "1/4 medium carrot", "description": ""}, {"name": "young corn", "description": "50g"}, {"name": "mushrooms", "description": "50g"}, {"name": "1/8 head cabbage", "description": ""}, {"name": "1/4 medium onion", "description": ""}, {"name": "garlic", "description": "1 clove"}, {"name": "oyster sauce", "description": "1 tbsp"}, {"name": "broth", "description": "1/4 cup"}, {"name": "cornstarch", "description": "1 tsp"}, {"name": "cooking oil", "description": "1 tsp"}]'::jsonb, '[{"title": "Step 1", "description": "Blanch snap peas and carrots briefly. Drain."}, {"title": "Step 2", "description": "Sauté garlic and onion."}, {"title": "Step 3", "description": "Add squid balls; cook until lightly browned."}, {"title": "Step 4", "description": "Add mushrooms and young corn."}, {"title": "Step 5", "description": "Add blanched vegetables and cabbage."}, {"title": "Step 6", "description": "Add quail eggs. Season with oyster sauce."}, {"title": "Step 7", "description": "Add broth; bring to simmer."}, {"title": "Step 8", "description": "Add cornstarch slurry; stir to thicken."}, {"title": "Step 9", "description": "Serve immediately."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Dinengdeng', 'Soup/Stew', '', 'Easy', '', '1 person', 'approximately 300 kcal per serving', 4294964192, '[{"name": "bagoong isda", "description": "1 tbsp"}, {"name": "water", "description": "1 cup"}, {"name": "kalabasa", "description": "1/4 cup"}, {"name": "ampalaya", "description": "1/4 cup"}, {"name": "young okra", "description": "1/4 cup"}, {"name": "eggplant", "description": "1/4 cup"}, {"name": "paria flowers", "description": "1/4 cup"}, {"name": "grilled or fried fish", "description": "1/2 pc"}]'::jsonb, '[{"title": "Step 1", "description": "Bring water and bagoong isda to a boil."}, {"title": "Step 2", "description": "Add kalabasa; cook 5 minutes."}, {"title": "Step 3", "description": "Add eggplant and ampalaya."}, {"title": "Step 4", "description": "Add okra and paria last."}, {"title": "Step 5", "description": "Add grilled fish."}, {"title": "Step 6", "description": "Simmer until all vegetables are just tender."}, {"title": "Step 7", "description": "Taste — the bagoong provides all the seasoning needed."}, {"title": "Step 8", "description": "Serve with rice."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Mongo con Hipon', 'Soup/Stew', '', 'Easy', '', '1 person', 'approximately 520 kcal per serving', 4294964192, '[{"name": "mung beans", "description": "1/4 cup"}, {"name": "shrimp", "description": "100g"}, {"name": "malunggay leaves", "description": "1/2 cup"}, {"name": "garlic", "description": "1 clove"}, {"name": "1/4 medium onion", "description": ""}, {"name": "1/2 medium tomato", "description": ""}, {"name": "1 1/2 cups water", "description": ""}, {"name": "fish sauce", "description": "1 tbsp"}, {"name": "cooking oil", "description": "1 tsp"}]'::jsonb, '[{"title": "Step 1", "description": "Boil soaked mung beans in water until tender (30-40 min)."}, {"title": "Step 2", "description": "In a separate pan, sauté garlic, onion, and tomatoes."}, {"title": "Step 3", "description": "Add shrimp; cook until pink."}, {"title": "Step 4", "description": "Combine with mung beans."}, {"title": "Step 5", "description": "Simmer together 10 minutes."}, {"title": "Step 6", "description": "Add malunggay; cook 2 minutes."}, {"title": "Step 7", "description": "Season with fish sauce. Serve."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Pinaputokang Isda', 'Braised', '', 'Medium', '', '1 person', 'approximately 950 kcal per serving', 4294964192, '[{"name": "1/2 whole tilapia or bangus", "description": ""}, {"name": "coconut milk", "description": "150ml"}, {"name": "1-inch ginger", "description": ""}, {"name": "1/4 medium onion", "description": ""}, {"name": "1/2 medium tomato", "description": ""}, {"name": "siling haba", "description": "1 pc"}, {"name": "fish sauce", "description": "1 tbsp"}]'::jsonb, '[{"title": "Step 1", "description": "Score fish with deep cuts."}, {"title": "Step 2", "description": "Layer ginger, onion, and tomatoes in pot."}, {"title": "Step 3", "description": "Place fish on top."}, {"title": "Step 4", "description": "Pour coconut milk over. Add chilis."}, {"title": "Step 5", "description": "Bring to a boil. Do not stir."}, {"title": "Step 6", "description": "Simmer until coconut milk reduces and fish skin ''bursts'' from the heat (about 20 minutes)."}, {"title": "Step 7", "description": "Season with fish sauce. Serve."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Mechado', 'Braised', '', 'Hard', '', '1 person', 'approximately 1700 kcal per serving', 4294964192, '[{"name": "beef chuck", "description": "180g"}, {"name": "pork fat", "description": "25g"}, {"name": "tomato sauce", "description": "100g"}, {"name": "soy sauce", "description": "1 tbsp"}, {"name": "water", "description": "1/4 cup"}, {"name": "1/2 medium potato", "description": ""}, {"name": "1/2 medium carrot", "description": ""}, {"name": "1/4 medium onion", "description": ""}, {"name": "garlic", "description": "1 clove"}, {"name": "bay leaf", "description": "1 pc"}, {"name": "cooking oil", "description": "1 tsp"}]'::jsonb, '[{"title": "Step 1", "description": "Insert pork fat strips into beef using a skewer or knife, distributing evenly."}, {"title": "Step 2", "description": "Marinate beef in soy sauce 30 minutes."}, {"title": "Step 3", "description": "Brown beef on all sides in hot oil."}, {"title": "Step 4", "description": "Sauté garlic and onion in same pot."}, {"title": "Step 5", "description": "Return beef. Add tomato sauce, soy sauce marinade, water, and bay leaves."}, {"title": "Step 6", "description": "Simmer covered 1.5 hours until very tender."}, {"title": "Step 7", "description": "Add potatoes and carrots. Cook 15 more minutes."}, {"title": "Step 8", "description": "Remove beef; slice. Reduce sauce. Pour over sliced beef."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Sinuglaw', 'Salad/Fresh', '', 'Medium', '', '1 person', 'approximately 850 kcal per serving', 4294964192, '[{"name": "pork belly, grilled and chopped", "description": "100g"}, {"name": "fresh tuna", "description": "100g"}, {"name": "coconut vinegar", "description": "1 tbsp"}, {"name": "calamansi juice", "description": "1 tbsp"}, {"name": "1-inch ginger", "description": ""}, {"name": "red onion", "description": "2 tbsp"}, {"name": "siling labuyo", "description": "1 pc"}, {"name": "coconut cream", "description": "1 tbsp"}, {"name": "Salt and pepper", "description": ""}]'::jsonb, '[{"title": "Step 1", "description": "Grill pork belly until charred and cooked. Chop into small pieces."}, {"title": "Step 2", "description": "Marinate tuna in vinegar and calamansi for 20 minutes."}, {"title": "Step 3", "description": "Drain some liquid from tuna."}, {"title": "Step 4", "description": "Add ginger, onion, and chili to tuna."}, {"title": "Step 5", "description": "Fold in grilled pork."}, {"title": "Step 6", "description": "Add coconut cream; toss."}, {"title": "Step 7", "description": "Season; serve cold."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Pyanggang', 'Grilled/Fried', '', 'Hard', '', '1 person', 'approximately 650 kcal per serving', 4294964192, '[{"name": "chicken pieces", "description": "150g"}, {"name": "grated coconut, toasted very dark", "description": "1/2 cup"}, {"name": "turmeric", "description": "1/4 tsp"}, {"name": "lemongrass", "description": "1 stalk"}, {"name": "garlic", "description": "1 clove"}, {"name": "1/2-inch ginger", "description": ""}, {"name": "siling labuyo", "description": "1 pc"}, {"name": "salt", "description": "1/4 tsp"}, {"name": "coconut oil", "description": "1 tsp"}]'::jsonb, '[{"title": "Step 1", "description": "Toast grated coconut in a dry pan, stirring constantly, until very dark brown — almost black."}, {"title": "Step 2", "description": "Cool; blend charred coconut with lemongrass, garlic, ginger, turmeric, and chili."}, {"title": "Step 3", "description": "This becomes a dark paste."}, {"title": "Step 4", "description": "Rub paste generously all over chicken pieces."}, {"title": "Step 5", "description": "Marinate 2-4 hours."}, {"title": "Step 6", "description": "Grill over charcoal until cooked through, basting with coconut oil."}, {"title": "Step 7", "description": "Serve with coconut rice (tiyula)."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Ginisang Repolyo', 'Sautéed', '', 'Easy', '', '1 person', 'approximately 400 kcal per serving', 4294964192, '[{"name": "1/8 head cabbage", "description": ""}, {"name": "shrimp", "description": "100g"}, {"name": "pork", "description": "75g"}, {"name": "garlic", "description": "1 clove"}, {"name": "1/4 medium onion", "description": ""}, {"name": "fish sauce", "description": "1 tbsp"}, {"name": "oyster sauce", "description": "1 tsp"}, {"name": "cooking oil", "description": "1 tsp"}, {"name": "Salt and pepper", "description": ""}]'::jsonb, '[{"title": "Step 1", "description": "Heat oil; sauté garlic and onion."}, {"title": "Step 2", "description": "Add pork; cook until done."}, {"title": "Step 3", "description": "Add shrimp; cook until pink."}, {"title": "Step 4", "description": "Add cabbage; stir-fry on high heat."}, {"title": "Step 5", "description": "Season with fish sauce and oyster sauce."}, {"title": "Step 6", "description": "Cook 3-4 minutes until cabbage is just tender but still has bite."}, {"title": "Step 7", "description": "Serve immediately."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Guisadong Toge', 'Sautéed', '', 'Easy', '', '1 person', 'approximately 750 kcal per serving', 4294964192, '[{"name": "toge", "description": "200g"}, {"name": "pork", "description": "75g"}, {"name": "garlic", "description": "1 clove"}, {"name": "1/4 medium onion", "description": ""}, {"name": "fish sauce", "description": "1 tbsp"}, {"name": "Salt and pepper", "description": ""}, {"name": "cooking oil", "description": "1 tsp"}]'::jsonb, '[{"title": "Step 1", "description": "Rinse and drain bean sprouts. Remove any brown tails."}, {"title": "Step 2", "description": "Heat oil on high heat."}, {"title": "Step 3", "description": "Sauté garlic until golden."}, {"title": "Step 4", "description": "Add onion and pork; cook until pork is done."}, {"title": "Step 5", "description": "Add toge; stir-fry quickly on high heat (1-2 minutes only)."}, {"title": "Step 6", "description": "Season with fish sauce, salt, and pepper."}, {"title": "Step 7", "description": "Serve immediately."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Adobong Sitaw', 'Sautéed', '', 'Easy', '', '1 person', 'approximately 900 kcal per serving', 4294964192, '[{"name": "sitaw", "description": "200g"}, {"name": "pork belly", "description": "100g"}, {"name": "garlic", "description": "1 clove"}, {"name": "vinegar", "description": "1 tbsp"}, {"name": "soy sauce", "description": "1 tsp"}, {"name": "peppercorns", "description": "1/8 tsp"}, {"name": "bay leaf", "description": "1 pc"}, {"name": "cooking oil", "description": "1 tsp"}]'::jsonb, '[{"title": "Step 1", "description": "Sauté garlic in oil until golden."}, {"title": "Step 2", "description": "Add pork; cook until browned."}, {"title": "Step 3", "description": "Add sitaw; stir-fry 2 minutes."}, {"title": "Step 4", "description": "Add vinegar; do not stir for 1 minute."}, {"title": "Step 5", "description": "Add soy sauce, peppercorns, and bay leaves."}, {"title": "Step 6", "description": "Simmer covered 8-10 minutes until sitaw is tender."}, {"title": "Step 7", "description": "Uncover; let sauce slightly reduce."}, {"title": "Step 8", "description": "Serve."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Lumpiang Sariwa', 'Salad/Fresh', '', 'Medium', '', '1 person', 'approximately 750 kcal per serving', 4294964192, '[{"name": "For filling: 75g ubod", "description": ""}, {"name": "pork", "description": "50g"}, {"name": "shrimp", "description": "40g"}, {"name": "cabbage", "description": "1/2 cup"}, {"name": "1/2 medium carrot", "description": ""}, {"name": "garlic", "description": "1 clove"}, {"name": "onion", "description": "2 tbsp"}, {"name": "For wrapper: 1 egg, 1/2 cup flour, 3/4 cup water, pinch salt, 1 tsp oil", "description": ""}, {"name": "For sauce: 1/3 cup water, 1 tbsp soy sauce, 1 tbsp sugar, 1 tsp cornstarch, 1 clove garlic", "description": ""}, {"name": "ettuce leaves", "description": "2 l"}]'::jsonb, '[{"title": "Step 1", "description": "Make wrappers: whisk eggs, flour, water, salt into thin crepe batter. Cook thin crepes in oiled pan. Set aside."}, {"title": "Step 2", "description": "Sauté garlic, onion, pork, shrimp. Add ubod, carrot, cabbage. Season with fish sauce."}, {"title": "Step 3", "description": "Make sauce: cook all sauce ingredients until thick and translucent."}, {"title": "Step 4", "description": "Lay wrapper flat; add lettuce leaf."}, {"title": "Step 5", "description": "Spoon filling onto lettuce."}, {"title": "Step 6", "description": "Roll wrapper around filling."}, {"title": "Step 7", "description": "Drizzle sauce generously over top."}, {"title": "Step 8", "description": "Garnish with crushed peanuts."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Pinaupong Manok', 'Braised', '', 'Easy', '', '1 person', 'approximately 550 kcal per serving', 4294964192, '[{"name": "chicken pieces", "description": "200g"}, {"name": "garlic", "description": "3 cloves"}, {"name": "1/4 medium onion", "description": ""}, {"name": "1-inch ginger", "description": ""}, {"name": "lemongrass", "description": "1 stalk"}, {"name": "Salt and pepper", "description": ""}, {"name": "rock salt for the base", "description": "1/4 cup"}]'::jsonb, '[{"title": "Step 1", "description": "Season chicken inside and out with salt and pepper."}, {"title": "Step 2", "description": "Stuff cavity with garlic, onion, ginger, and lemongrass."}, {"title": "Step 3", "description": "Pour rock salt in bottom of heavy pot or clay pot."}, {"title": "Step 4", "description": "Place stuffed chicken upright on the salt bed."}, {"title": "Step 5", "description": "Cover tightly with foil then lid."}, {"title": "Step 6", "description": "Cook on low heat for 60-75 minutes — no peeking, no water added."}, {"title": "Step 7", "description": "Chicken steams in its own juices."}, {"title": "Step 8", "description": "Rest 10 minutes; serve with the natural juices."}]'::jsonb);
INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps) VALUES ('Tortang Talong', 'Grilled/Fried', '', 'Easy', '', '1 person', 'approximately 300 kcal per serving', 4294964192, '[{"name": "1 medium talong", "description": ""}, {"name": "arge egg", "description": "1 l"}, {"name": "garlic", "description": "1 clove"}, {"name": "1/4 medium onion", "description": ""}, {"name": "Salt and pepper", "description": ""}, {"name": "cooking oil", "description": "1 tbsp"}]'::jsonb, '[{"title": "Step 1", "description": "Grill or char eggplant over open flame until completely soft."}, {"title": "Step 2", "description": "Peel skin carefully; keep stem intact."}, {"title": "Step 3", "description": "Flatten eggplant with a fork."}, {"title": "Step 4", "description": "Season beaten eggs with garlic, onion, salt, and pepper."}, {"title": "Step 5", "description": "Dip eggplant in egg mixture, letting it absorb."}, {"title": "Step 6", "description": "Pan-fry in hot oil on medium heat until egg is set and golden."}, {"title": "Step 7", "description": "Flip carefully; fry other side."}, {"title": "Step 8", "description": "Serve with banana ketchup or garlic rice."}]'::jsonb);
